-- ======================================================================
-- migrations/2026-11-21-v21-security.sql
-- ======================================================================
-- PrintQR v21 migration (2026-11-21): security clean-up. Safe to run more than once.
-- 1. finalize_order stays server-only: orders must go through finalize-order (real page count, v11).
-- 2. The old captcha path (upload-pass + create_order_checked, v9) is gone; nothing calls it.
-- 3. shops.logo_url may only point at the shop's own file in the shop-logos bucket.

-- 1
revoke execute on function public.finalize_order(uuid, uuid) from public, anon, authenticated;
grant execute on function public.finalize_order(uuid, uuid) to service_role;

-- 2
drop function if exists public.create_order_checked(uuid, text, text, text, jsonb, uuid);
drop table if exists public.upload_pass;

-- 3
update public.shops set logo_url = null
where logo_url is not null
  and logo_url not like 'https://asqgdgzxkdksoikmffmd.supabase.co/storage/v1/object/public/shop-logos/' || id::text || '/%';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'shops_logo_url_own_bucket') then
    alter table public.shops add constraint shops_logo_url_own_bucket check (
      logo_url is null
      or logo_url like 'https://asqgdgzxkdksoikmffmd.supabase.co/storage/v1/object/public/shop-logos/' || id::text || '/%');
  end if;
end $$;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-21-v22-billing-idem.sql
-- ======================================================================
-- PrintQR v22 migration (2026-11-21): billing idempotency. Safe to run more than once.
-- 1. billing_events.event_id must be unique: the webhook now inserts the event first and skips it on a conflict.
--    (v3 created it as the primary key; this only adds a unique index if that is somehow missing.)
-- 2. billing_credits: extra days carried onto a new subscription (unused days of the plan it replaced),
--    written once per subscription id, so repeated webhooks / checkouts never add the days twice.

-- 1
do $$ begin
  if not exists (
    select 1
    from pg_index i
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = any (i.indkey)
    where i.indrelid = 'public.billing_events'::regclass
      and i.indisunique
      and i.indnkeyatts = 1
      and a.attname = 'event_id'
  ) then
    delete from public.billing_events e
      using public.billing_events d
      where e.event_id = d.event_id and e.ctid > d.ctid;
    create unique index if not exists billing_events_event_id_key on public.billing_events(event_id);
  end if;
end $$;

-- 2
create table if not exists public.billing_credits (
  sub_id text primary key,
  shop_id uuid not null,
  days int not null check (days >= 0),
  reason text,
  created_at timestamptz not null default now()
);
create index if not exists billing_credits_shop on public.billing_credits(shop_id);
alter table public.billing_credits enable row level security;
-- No policies: only the service role (Edge Functions) uses it.
revoke all on public.billing_credits from public, anon, authenticated;
grant all on public.billing_credits to service_role;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-21-v23-idcard-reorder-paper.sql
-- ======================================================================
-- PrintQR v23 migration (2026-11-21): ID card sheet, "print again" (reorder), paper stock.
-- Safe to run more than once. Needs v4 (pg_net, private.cron_tokens), v14 (push), v17 (plan features), v18.
-- Then deploy the Edge Functions: reorder (new), finalize-order, push-new-order.
--
-- A. ID card print sheet (Pro / Plus, like the passport sheet): order_files.item_kind 'idcard'.
--    The customer's phone makes one A4 page (front above back at real card size, 85.6 x 54 mm);
--    price = copies x rates.idcard_sheet (20 when the shop has not set it). Free shops: rejected.
-- B. Print again: reorder() makes a NEW order (new token) from an old order's files, priced again on
--    the server. The files are not uploaded again: the Edge Function 'reorder' copies each stored object
--    to the new order's own path (order_files.source_path says where from), then reorder_finalize()
--    queues the order. Every order keeps its own objects, so one order's auto-delete never removes
--    another order's files.
-- C. Paper stock (all plans): shops.paper_sheets (null = not tracked), paper_low_at (default 200),
--    paper_alerted_at. When an order becomes 'done' its sheets are taken off once (orders.paper_used);
--    when the stock drops below paper_low_at the owner's phones get one push (again only after a top-up).

-- ============ A. ID card sheet ============

alter table public.order_files drop constraint if exists order_files_item_kind_check;
alter table public.order_files add constraint order_files_item_kind_check check (item_kind in ('print', 'passport', 'idcard'));

-- ID card item (Pro only): {"kind":"idcard","name":"id-card.pdf","mime":"application/pdf","size":1234,"copies":2,"color":true}
--   -> 1 page, printed `copies` times, price = copies x rates.idcard_sheet (default 20)
create or replace function public.create_order(p_slug text, p_customer_name text, p_note text, p_files jsonb, p_counter uuid default null)
returns table (order_id uuid, access_key uuid, token int, shop_id uuid, total numeric, paths text[])
language plpgsql security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_pro boolean;
  v_order public.orders;
  v_token int;
  v_total numeric(10,2) := 0;
  v_paths text[] := '{}';
  v_f jsonb;
  v_i int := 0;
  v_rate numeric;
  v_pages int;
  v_total_pages int;
  v_copies int;
  v_color boolean;
  v_duplex boolean;
  v_binding boolean;
  v_lam boolean;
  v_kind text;
  v_photos int;
  v_range text;
  v_price numeric(10,2);
  v_path text;
  v_counter_id uuid;
  v_counter_name text;
  v_ip text;
  v_ext text;
  v_mime text;
  v_size bigint;
  v_bytes bigint := 0;
  v_max bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Kolkata')) at time zone 'Asia/Kolkata';
begin
  select * into v_shop from public.shops where slug = p_slug for update;
  if not found then raise exception 'Shop not found'; end if;
  if not v_shop.is_open then raise exception 'Shop is closed right now'; end if;
  if p_files is null or jsonb_typeof(p_files) <> 'array' or jsonb_array_length(p_files) = 0 then
    raise exception 'No files';
  end if;
  if jsonb_array_length(p_files) > 20 then raise exception 'Max 20 files per order'; end if;

  -- Anti-spam (per 10 minutes, not per day: orders per day are unlimited on every plan).
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.order_rate where created_at < now() - interval '1 day';
    if (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many orders from this network. Please wait a few minutes and try again.';
    end if;
  end if;
  if (select count(*) from public.orders o where o.shop_id = v_shop.id and o.status = 'uploading'
        and o.created_at > now() - interval '30 minutes') >= 20
     or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'This shop is getting too many orders right now. Please try again in a few minutes.';
  end if;

  -- File checks: only print-able types, real sizes, each file up to 50 MB, the order up to the plan's size.
  v_max := public.plan_order_bytes(v_shop);
  for v_f in select * from jsonb_array_elements(p_files) loop
    v_ext := lower(substring(coalesce(v_f->>'name', '') from '\.([A-Za-z0-9]+)$'));
    v_mime := public.upload_mime_for(v_ext);
    if v_mime is null or coalesce(v_f->>'mime', '') <> v_mime then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    if v_f->>'kind' = 'idcard' and v_mime <> 'application/pdf' then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    v_size := coalesce((v_f->>'size')::bigint, 0);
    if v_size < 1 or v_size > 52428800 then raise exception 'Each file must be under 50 MB'; end if;
    v_bytes := v_bytes + v_size;
  end loop;
  if v_bytes > v_max then raise exception 'This shop accepts up to % MB per order', v_max / 1048576; end if;
  if v_ip is not null then insert into public.order_rate (ip_hash) values (v_ip); end if;
  v_pro := public.is_pro(v_shop);
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'passport') then
    raise exception 'Passport photo sheet is not available at this shop';
  end if;
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'idcard') then
    raise exception 'ID card sheet is not available at this shop';
  end if;

  if p_counter is not null then
    select c.id, c.name into v_counter_id, v_counter_name
      from public.counters c where c.id = p_counter and c.shop_id = v_shop.id
        and (v_pro or c.id in (
          select c2.id from public.counters c2 where c2.shop_id = v_shop.id
          order by c2.created_at, c2.id limit public.free_counter_limit()));
  end if;

  select coalesce(max(o.token), 0) + 1 into v_token
    from public.orders o where o.shop_id = v_shop.id and o.created_at >= v_day_start;

  insert into public.orders (shop_id, token, customer_name, note, counter_id, counter_name)
    values (v_shop.id, v_token, nullif(left(trim(coalesce(p_customer_name,'')), 60), ''),
      nullif(left(trim(coalesce(p_note,'')), 300), ''), v_counter_id, v_counter_name)
    returning * into v_order;

  for v_f in select * from jsonb_array_elements(p_files) loop
    v_i := v_i + 1;
    v_kind := case when v_f->>'kind' in ('passport', 'idcard') then v_f->>'kind' else 'print' end;
    v_binding := false;
    v_lam := false;
    if v_kind = 'passport' then
      v_photos := greatest(1, least(300, coalesce((v_f->>'photos')::int, 8)));
      v_pages := ceil(v_photos / 30.0)::int;
      v_total_pages := v_pages;
      v_copies := 1;
      v_color := true;
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40);
      v_price := round(v_pages * v_copies * v_rate, 2);
    elsif v_kind = 'idcard' then
      -- One A4 page (front above back). finalize-order checks the PDF really has one page.
      v_photos := null;
      v_pages := 1;
      v_total_pages := 1;
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, true);
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'idcard_sheet')::numeric, 20);
      v_price := round(v_copies * v_rate, 2);
    else
      v_photos := null;
      v_pages := greatest(1, least(2000, coalesce((v_f->>'pages_to_print')::int, 1)));
      v_total_pages := greatest(1, least(2000, coalesce((v_f->>'total_pages')::int, 1)));
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, false);
      v_duplex := coalesce((v_f->>'duplex')::boolean, false);
      -- Extras only when the shop has a rate for them (0 / missing = not offered).
      v_binding := coalesce((v_f->>'binding')::boolean, false) and coalesce((v_shop.rates ->> 'binding')::numeric, 0) > 0;
      v_lam := coalesce((v_f->>'lamination')::boolean, false) and coalesce((v_shop.rates ->> 'lamination')::numeric, 0) > 0;
      v_range := nullif(left(v_f->>'page_range', 60), '');
      v_price := public.file_price(v_shop.rates, v_pages, v_copies, v_color, v_duplex, v_binding, v_lam);
    end if;
    v_total := v_total + v_price;
    v_path := v_shop.id::text || '/' || v_order.id::text || '/' || v_i::text || '-' ||
      left(regexp_replace(coalesce(v_f->>'name','file'), '[^A-Za-z0-9._-]', '_', 'g'), 80);
    v_paths := v_paths || v_path;
    insert into public.order_files (order_id, shop_id, storage_path, file_name, mime, size_bytes,
        total_pages, page_range, pages_to_print, copies, color, duplex, price, item_kind, photos, binding, lamination)
      values (v_order.id, v_shop.id, v_path, left(coalesce(v_f->>'name','file'), 200), v_f->>'mime',
        (v_f->>'size')::bigint, v_total_pages, v_range, v_pages, v_copies, v_color, v_duplex, v_price,
        v_kind, v_photos, v_binding, v_lam);
  end loop;

  update public.orders set total = v_total where id = v_order.id;

  return query select v_order.id, v_order.access_key, v_token, v_shop.id, v_total, v_paths;
end $$;
grant execute on function public.create_order(text, text, text, jsonb, uuid) to anon, authenticated;

-- Upload page: Pro shops also get the ID card rate (20 when not set); free shops get neither sheet rate,
-- so even an old cached app hides both options. Same columns as v17.
create or replace function public.get_shop_public(p_slug text)
returns table (id uuid, name text, address text, is_open boolean, rates jsonb, upi_id text, is_pro boolean,
  is_plus boolean, logo_url text, brand_color text, max_order_mb int, file_hours int, hours jsonb)
language sql stable security definer set search_path = public as $$
  select s.id, s.name, s.address, s.is_open,
    case when public.is_pro(s) then jsonb_build_object('passport_sheet', 40, 'idcard_sheet', 20) || s.rates
         else s.rates - 'passport_sheet' - 'idcard_sheet' end,
    s.upi_id, public.is_pro(s),
    public.is_plus(s),
    case when public.is_plus(s) then s.logo_url end,
    case when public.is_plus(s) then s.brand_color end,
    (public.plan_order_bytes(s) / 1048576)::int,
    public.shop_file_hours(s),
    case when coalesce((s.hours->>'enabled')::boolean, false) then s.hours end
  from public.shops s where s.slug = p_slug and not s.blocked;
$$;
grant execute on function public.get_shop_public(text) to anon, authenticated;

-- ============ B. Print again (reorder) ============

-- Set only on a reorder's files: the object (of the earlier order, same shop) the file is copied from.
alter table public.order_files add column if not exists source_path text;

-- Customers may upload only to their own new order's paths, never to a reorder's (those are copied on the server).
create or replace function public.can_upload(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.order_files f join public.orders o on o.id = f.order_id
    where f.storage_path = p_name and f.source_path is null
      and o.status = 'uploading' and o.created_at > now() - interval '30 minutes'
  );
$$;
grant execute on function public.can_upload(text) to anon, authenticated;

-- Status page: may this order be printed again, and with what files / rates.
create or replace function public.reorder_info(p_order_id uuid, p_key uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_order public.orders;
  v_shop public.shops;
  v_pro boolean;
begin
  select * into v_order from public.orders o where o.id = p_order_id and o.access_key = p_key;
  if not found then raise exception 'Order not found'; end if;
  select * into v_shop from public.shops s where s.id = v_order.shop_id;
  v_pro := public.is_pro(v_shop);
  return jsonb_build_object(
    'can', not v_order.files_deleted and v_order.status in ('received', 'printing', 'ready', 'done')
           and v_shop.is_open and not v_shop.blocked,
    'is_open', v_shop.is_open and not v_shop.blocked,
    'rates', case when v_pro then jsonb_build_object('passport_sheet', 40, 'idcard_sheet', 20) || v_shop.rates
                  else v_shop.rates - 'passport_sheet' - 'idcard_sheet' end,
    'files', case when v_order.files_deleted then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', f.id, 'file_name', f.file_name, 'item_kind', f.item_kind, 'pages', f.pages_to_print,
          'copies', f.copies, 'color', f.color, 'duplex', f.duplex, 'binding', f.binding,
          'lamination', f.lamination, 'photos', f.photos,
          'allowed', f.item_kind = 'print' or v_pro)
        order by coalesce(substring(f.storage_path from '/([0-9]+)-[^/]*$')::int, 0), f.id)
      from public.order_files f where f.order_id = v_order.id), '[]'::jsonb) end
  );
end $$;
revoke all on function public.reorder_info(uuid, uuid) from public;
grant execute on function public.reorder_info(uuid, uuid) to anon, authenticated;

-- p_items: [{"file_id": "<order_files.id of the old order>", "copies": 1..100, "color": true|false}, ...]
-- Pages, sides, binding and lamination stay as they were; the price is worked out again with today's rates.
-- The new order waits in 'uploading' (hidden from the shop) until the Edge Function 'reorder' has copied
-- the files and called reorder_finalize(). If that never happens, the cleanup job cancels it after 1 hour.
create or replace function public.reorder(p_order_id uuid, p_key uuid, p_items jsonb)
returns table (order_id uuid, access_key uuid, token int, shop_id uuid, total numeric)
language plpgsql security definer set search_path = public as $$
declare
  v_src public.orders;
  v_shop public.shops;
  v_pro boolean;
  v_order public.orders;
  v_token int;
  v_total numeric(10,2) := 0;
  v_item jsonb;
  v_f public.order_files;
  v_i int := 0;
  v_copies int;
  v_color boolean;
  v_binding boolean;
  v_lam boolean;
  v_price numeric(10,2);
  v_path text;
  v_bytes bigint := 0;
  v_max bigint;
  v_ip text;
  v_seen uuid[] := '{}';
  v_counter_id uuid;
  v_counter_name text;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Kolkata')) at time zone 'Asia/Kolkata';
begin
  select * into v_src from public.orders o where o.id = p_order_id and o.access_key = p_key;
  if not found then raise exception 'Order not found'; end if;
  if v_src.files_deleted then raise exception 'The files of this order are already deleted. Please send them again.'; end if;
  if v_src.status not in ('received', 'printing', 'ready', 'done') then raise exception 'This order cannot be printed again'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'No files';
  end if;
  if jsonb_array_length(p_items) > 20 then raise exception 'Max 20 files per order'; end if;

  select * into v_shop from public.shops s where s.id = v_src.shop_id for update;
  if not found or v_shop.blocked then raise exception 'Shop not found'; end if;
  if not v_shop.is_open then raise exception 'Shop is closed right now'; end if;

  -- Same anti-spam as create_order.
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.order_rate where created_at < now() - interval '1 day';
    if (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many orders from this network. Please wait a few minutes and try again.';
    end if;
  end if;
  if (select count(*) from public.orders o where o.shop_id = v_shop.id and o.status = 'uploading'
        and o.created_at > now() - interval '30 minutes') >= 20
     or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'This shop is getting too many orders right now. Please try again in a few minutes.';
  end if;

  -- Check every item before anything is written: own files only, once each, copies 1-100, plan still allows it.
  v_pro := public.is_pro(v_shop);
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' or coalesce(v_item->>'file_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'File not found';
    end if;
    select * into v_f from public.order_files f where f.id = (v_item->>'file_id')::uuid and f.order_id = v_src.id;
    if not found or v_f.id = any (v_seen) then raise exception 'File not found'; end if;
    v_seen := v_seen || v_f.id;
    if coalesce(v_item->>'copies', '') !~ '^[0-9]{1,3}$' then raise exception 'Copies must be from 1 to 100'; end if;
    if (v_item->>'copies')::int not between 1 and 100 then raise exception 'Copies must be from 1 to 100'; end if;
    if v_item ? 'color' and jsonb_typeof(v_item->'color') <> 'boolean' then raise exception 'Bad print option'; end if;
    if v_f.item_kind = 'passport' and not v_pro then raise exception 'Passport photo sheet is not available at this shop'; end if;
    if v_f.item_kind = 'idcard' and not v_pro then raise exception 'ID card sheet is not available at this shop'; end if;
    v_bytes := v_bytes + coalesce(v_f.size_bytes, 0);
  end loop;
  v_max := public.plan_order_bytes(v_shop);
  if v_bytes > v_max then raise exception 'This shop accepts up to % MB per order', v_max / 1048576; end if;
  if v_ip is not null then insert into public.order_rate (ip_hash) values (v_ip); end if;

  -- Same counter as before (if it still exists and the plan still allows it), else the main queue.
  if v_src.counter_id is not null then
    select c.id, c.name into v_counter_id, v_counter_name
      from public.counters c where c.id = v_src.counter_id and c.shop_id = v_shop.id
        and (v_pro or c.id in (
          select c2.id from public.counters c2 where c2.shop_id = v_shop.id
          order by c2.created_at, c2.id limit public.free_counter_limit()));
  end if;

  select coalesce(max(o.token), 0) + 1 into v_token
    from public.orders o where o.shop_id = v_shop.id and o.created_at >= v_day_start;

  insert into public.orders (shop_id, token, customer_name, note, counter_id, counter_name, lang)
    values (v_shop.id, v_token, v_src.customer_name, v_src.note, v_counter_id, v_counter_name, v_src.lang)
    returning * into v_order;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_i := v_i + 1;
    select * into v_f from public.order_files f where f.id = (v_item->>'file_id')::uuid and f.order_id = v_src.id;
    v_copies := (v_item->>'copies')::int;
    v_binding := false;
    v_lam := false;
    if v_f.item_kind = 'passport' then
      v_color := true;
      v_price := round(v_f.pages_to_print * v_copies * coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40), 2);
    elsif v_f.item_kind = 'idcard' then
      v_color := coalesce((v_item->>'color')::boolean, v_f.color);
      v_price := round(v_copies * coalesce((v_shop.rates ->> 'idcard_sheet')::numeric, 20), 2);
    else
      v_color := coalesce((v_item->>'color')::boolean, v_f.color);
      v_binding := v_f.binding and coalesce((v_shop.rates ->> 'binding')::numeric, 0) > 0;
      v_lam := v_f.lamination and coalesce((v_shop.rates ->> 'lamination')::numeric, 0) > 0;
      v_price := public.file_price(v_shop.rates, v_f.pages_to_print, v_copies, v_color, v_f.duplex, v_binding, v_lam);
    end if;
    v_total := v_total + v_price;
    v_path := v_shop.id::text || '/' || v_order.id::text || '/' || v_i::text || '-' ||
      left(regexp_replace(coalesce(v_f.file_name, 'file'), '[^A-Za-z0-9._-]', '_', 'g'), 80);
    insert into public.order_files (order_id, shop_id, storage_path, file_name, mime, size_bytes,
        total_pages, page_range, pages_to_print, copies, color, duplex, price, item_kind, photos, binding, lamination, source_path)
      values (v_order.id, v_shop.id, v_path, v_f.file_name, v_f.mime, v_f.size_bytes,
        v_f.total_pages, v_f.page_range, v_f.pages_to_print, v_copies, v_color, v_f.duplex, v_price,
        v_f.item_kind, v_f.photos, v_binding, v_lam, v_f.storage_path);
  end loop;

  update public.orders set total = v_total where id = v_order.id;

  return query select v_order.id, v_order.access_key, v_token, v_shop.id, v_total;
end $$;
revoke all on function public.reorder(uuid, uuid, jsonb) from public;
grant execute on function public.reorder(uuid, uuid, jsonb) to anon, authenticated;

-- Edge Function 'reorder' (service role), after copying: every copy must be there, then the order goes
-- to the shop ('received' -> new-order push, as for a normal order).
create or replace function public.reorder_finalize(p_order_id uuid, p_key uuid)
returns numeric language plpgsql security definer set search_path = public as $$
declare
  v_order public.orders;
  v_missing int;
begin
  select * into v_order from public.orders o
    where o.id = p_order_id and o.access_key = p_key and o.status = 'uploading' for update;
  if not found then raise exception 'Order not found'; end if;
  -- Only reorders (every file has a source); normal orders go through finalize_order_counted.
  if not exists (select 1 from public.order_files f where f.order_id = v_order.id)
     or exists (select 1 from public.order_files f where f.order_id = v_order.id and f.source_path is null) then
    raise exception 'Order not found';
  end if;
  select count(*) into v_missing from public.order_files f
    where f.order_id = v_order.id and not exists (
      select 1 from storage.objects so
      where so.bucket_id = 'uploads' and so.name = f.storage_path
        and coalesce((so.metadata->>'size')::bigint, f.size_bytes) = f.size_bytes);
  if v_missing > 0 then raise exception 'Some files could not be copied. Please try again.'; end if;
  update public.orders set status = 'received', updated_at = now() where id = v_order.id;
  return v_order.total;
end $$;
revoke all on function public.reorder_finalize(uuid, uuid) from public, anon, authenticated;
grant execute on function public.reorder_finalize(uuid, uuid) to service_role;

-- ============ C. Paper stock + low alert (all plans) ============

alter table public.shops add column if not exists paper_sheets int;            -- null = not tracked
alter table public.shops add column if not exists paper_low_at int not null default 200;
alter table public.shops add column if not exists paper_alerted_at timestamptz; -- set by the trigger only
alter table public.shops drop constraint if exists shops_paper_check;
alter table public.shops add constraint shops_paper_check check (
  (paper_sheets is null or paper_sheets between 0 and 10000000) and paper_low_at between 0 and 10000000);
grant update (paper_sheets, paper_low_at) on public.shops to authenticated;

-- Sheets an order used (set once, when it first becomes 'done'). Not owner-editable.
alter table public.orders add column if not exists paper_used int;

-- Below the limit -> remember the alert (and push when the drop came from printed orders);
-- back at or above the limit (top-up) or tracking off -> forget it, so the next drop alerts again.
-- Not security definer on purpose: current_user tells an owner's own edit ('authenticated', no push:
-- they just typed the number) from the orders trigger below (definer).
create or replace function public.shops_paper_alert()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.paper_sheets is null or new.paper_sheets >= new.paper_low_at then
    new.paper_alerted_at := null;
  elsif new.paper_alerted_at is null then
    new.paper_alerted_at := now();
    if current_user not in ('authenticated', 'anon') then
      begin
        perform net.http_post(
          url := 'https://asqgdgzxkdksoikmffmd.supabase.co/functions/v1/push-new-order',
          body := jsonb_build_object('kind', 'paper_low', 'shop_id', new.id),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-cron-token', (select token from private.cron_tokens where name = 'push')
          ),
          timeout_milliseconds := 10000
        );
      exception when others then
        null;  -- a notification problem must never block the stock update
      end;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists shops_paper_alert on public.shops;
create trigger shops_paper_alert before update of paper_sheets, paper_low_at on public.shops
  for each row execute function public.shops_paper_alert();

-- Order marked done: take its sheets off the stock once (never below 0; nothing when not tracked).
-- Per file: both sides -> pages / 2 rounded up, else pages; x copies. Passport / ID card: sheets x copies.
create or replace function public.orders_paper_used()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_used int;
begin
  if new.status = 'done' and old.status is distinct from 'done' and new.paper_used is null then
    select coalesce(sum(
        (case when f.item_kind = 'print' and f.duplex then ceil(f.pages_to_print / 2.0)::int else f.pages_to_print end)
        * f.copies), 0)::int
      into v_used
      from public.order_files f where f.order_id = new.id;
    update public.shops set paper_sheets = greatest(0, paper_sheets - v_used)
      where id = new.shop_id and paper_sheets is not null and v_used > 0;
    new.paper_used := v_used;
  end if;
  return new;
exception when others then
  return new;  -- paper counting must never block an order's status
end $$;
drop trigger if exists orders_paper_used on public.orders;
create trigger orders_paper_used before update of status on public.orders
  for each row execute function public.orders_paper_used();

notify pgrst, 'reload schema';

-- Checks:
--   select conname, pg_get_constraintdef(oid) from pg_constraint where conname = 'order_files_item_kind_check';
--   select id, name, paper_sheets, paper_low_at, paper_alerted_at from public.shops where paper_sheets is not null;
--   select id, status_code, content from net._http_response order by created desc limit 5;

-- ======================================================================
-- migrations/2026-11-21-v24-photo-thumbs.sql
-- ======================================================================
-- PrintQR v24 migration (2026-11-21): small photo thumbnails for the owner's order list.
-- Safe to run more than once. Needs v23.
--
-- The customer's phone makes a small JPEG (about 10 KB) of every photo it uploads and stores it next to
-- the photo as '<storage_path>.thumb.jpg'. The owner's order list shows that instead of downloading the
-- full photo for every thumbnail (Supabase image transformations need a paid Supabase plan).
-- Same rules as the photo itself: only the order's own new paths, only while it is uploading (30 min).
-- Old orders and reorders have no thumbnail; the app then falls back to the full photo.

create or replace function public.can_upload(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.order_files f join public.orders o on o.id = f.order_id
    where f.source_path is null
      and o.status = 'uploading' and o.created_at > now() - interval '30 minutes'
      and (f.storage_path = p_name
           or (p_name = f.storage_path || '.thumb.jpg' and f.mime like 'image/%'))
  );
$$;
grant execute on function public.can_upload(text) to anon, authenticated;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-22-v25-launch-safety.sql
-- ======================================================================
-- PrintQR v25 migration (2026-11-22): launch safety (P0 fixes 2, 3, 4, 5, 8, 10). Safe to run more than once. Needs v24.
--
-- 1. Files of orders not printed yet are kept: Received / Printing orders keep their files until the shop
--    moves them on (or at most 48 hours, or the plan's time if longer). Free plan: 3 hours (was 1).
--    Unfinished uploads are removed after 35 minutes (was 1 hour).
-- 2. Storage budgets: per shop (Free 150 MB, Pro / Plus 500 MB of files not yet deleted) and for the whole
--    service (700 MB, below the 1 GB Supabase Free storage). Change them in app_settings.
-- 3. Bot check only when needed: create_order(..., p_pass) asks for a Turnstile pass (upload-pass function)
--    when one network sent 3+ orders or one shop got 20+ orders in 10 minutes. app_settings.order_captcha:
--    'auto' (default) / 'always' / 'off'.
-- 4. "Block sender": the shop owner can block the network an order came from (and cancel its open orders).
--    The network id (a hash) is kept in order_senders, which shop owners cannot read.
-- 5. finalize-order may run at most 5 times per order (finalize_begin).
-- 6. ops_events + ops_health() for the "Health check" GitHub workflow (alerts, storage / database size).

-- ============ settings ============
alter table public.app_settings add column if not exists order_captcha text not null default 'auto';
alter table public.app_settings add column if not exists storage_budget_mb int not null default 700;
alter table public.app_settings add column if not exists shop_storage_free_mb int not null default 150;
alter table public.app_settings add column if not exists shop_storage_paid_mb int not null default 500;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'app_settings_order_captcha_check') then
    alter table public.app_settings add constraint app_settings_order_captcha_check check (order_captcha in ('off', 'auto', 'always'));
  end if;
end $$;

create or replace function public.storage_budget_bytes()
returns bigint language sql stable security definer set search_path = public as $$
  select coalesce((select storage_budget_mb from public.app_settings where id = 1), 700)::bigint * 1048576;
$$;
revoke all on function public.storage_budget_bytes() from public, anon, authenticated;

create or replace function public.shop_storage_bytes(s public.shops)
returns bigint language sql stable security definer set search_path = public as $$
  select (case when public.shop_tier(s) = 'free'
    then coalesce((select shop_storage_free_mb from public.app_settings where id = 1), 150)
    else coalesce((select shop_storage_paid_mb from public.app_settings where id = 1), 500) end)::bigint * 1048576;
$$;
revoke all on function public.shop_storage_bytes(public.shops) from public, anon, authenticated;

-- ============ 1. retention ============
create or replace function public.plan_file_hours(s public.shops)
returns int language sql stable set search_path = public as $$
  select case public.shop_tier(s) when 'plus' then 168 when 'pro' then 24 else 3 end;
$$;

create or replace function public.cleanup_candidates()
returns table (order_id uuid, status text, paths text[])
language sql stable security definer set search_path = public as $$
  select o.id, o.status, array(select f.storage_path from public.order_files f where f.order_id = o.id)
  from public.orders o join public.shops s on s.id = o.shop_id
  where o.files_deleted = false and (
    (o.status = 'uploading' and o.created_at < now() - interval '35 minutes')
    or (o.status in ('ready', 'done', 'cancelled') and o.created_at < now() - make_interval(hours => public.shop_file_hours(s)))
    or (o.status in ('received', 'printing')
        and o.created_at < now() - make_interval(hours => greatest(public.shop_file_hours(s), 48)))
  )
  limit 500;
$$;
revoke all on function public.cleanup_candidates() from public, anon, authenticated;
grant execute on function public.cleanup_candidates() to service_role;

create index if not exists orders_live_files_idx on public.orders (shop_id) where files_deleted = false;

-- ============ 3 + 4. tables ============
create table if not exists public.upload_pass (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now()
);
alter table public.upload_pass enable row level security;
revoke all on public.upload_pass from anon, authenticated;
grant select, insert, delete on public.upload_pass to service_role;

create table if not exists public.order_senders (
  order_id uuid primary key references public.orders (id) on delete cascade,
  shop_id uuid not null references public.shops (id) on delete cascade,
  ip_hash text not null,
  created_at timestamptz not null default now()
);
create index if not exists order_senders_shop_ip_idx on public.order_senders (shop_id, ip_hash);
alter table public.order_senders enable row level security;
revoke all on public.order_senders from anon, authenticated;
grant select on public.order_senders to service_role;

create table if not exists public.shop_blocked_senders (
  shop_id uuid not null references public.shops (id) on delete cascade,
  ip_hash text not null,
  created_at timestamptz not null default now(),
  primary key (shop_id, ip_hash)
);
alter table public.shop_blocked_senders enable row level security;
revoke all on public.shop_blocked_senders from anon, authenticated;
grant select on public.shop_blocked_senders to service_role;

-- ============ create_order with p_pass ============
-- The old 5-argument version is replaced (old apps still call it with 4 or 5 arguments: p_pass has a default).
drop function if exists public.create_order(text, text, text, jsonb, uuid);
create or replace function public.create_order(p_slug text, p_customer_name text, p_note text, p_files jsonb, p_counter uuid default null,
  p_pass uuid default null)
returns table (order_id uuid, access_key uuid, token int, shop_id uuid, total numeric, paths text[])
language plpgsql security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_pro boolean;
  v_order public.orders;
  v_token int;
  v_total numeric(10,2) := 0;
  v_paths text[] := '{}';
  v_f jsonb;
  v_i int := 0;
  v_rate numeric;
  v_pages int;
  v_total_pages int;
  v_copies int;
  v_color boolean;
  v_duplex boolean;
  v_binding boolean;
  v_lam boolean;
  v_kind text;
  v_photos int;
  v_range text;
  v_price numeric(10,2);
  v_path text;
  v_counter_id uuid;
  v_counter_name text;
  v_ip text;
  v_ext text;
  v_mime text;
  v_size bigint;
  v_bytes bigint := 0;
  v_max bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Kolkata')) at time zone 'Asia/Kolkata';
  v_mode text;
  v_live_shop bigint;
  v_live_all bigint;
  v_cap_shop bigint;
  v_cap_all bigint;
begin
  select * into v_shop from public.shops where slug = p_slug for update;
  if not found then raise exception 'Shop not found'; end if;
  if not v_shop.is_open then raise exception 'Shop is closed right now'; end if;
  if p_files is null or jsonb_typeof(p_files) <> 'array' or jsonb_array_length(p_files) = 0 then
    raise exception 'No files';
  end if;
  if jsonb_array_length(p_files) > 20 then raise exception 'Max 20 files per order'; end if;

  -- Anti-spam (per 10 minutes, not per day: orders per day are unlimited on every plan).
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.order_rate where created_at < now() - interval '1 day';
    if (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many orders from this network. Please wait a few minutes and try again.';
    end if;
  end if;
  if (select count(*) from public.orders o where o.shop_id = v_shop.id and o.status = 'uploading'
        and o.created_at > now() - interval '30 minutes') >= 20
     or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'This shop is getting too many orders right now. Please try again in a few minutes.';
  end if;

  -- v25: the shop owner blocked this network ("Block sender" on an order).
  if v_ip is not null and exists (select 1 from public.shop_blocked_senders b where b.shop_id = v_shop.id and b.ip_hash = v_ip) then
    raise exception 'This shop is not accepting orders from your network.';
  end if;

  -- v25: bot check only when an order looks automated ('auto'), always ('always') or never ('off').
  -- 'captcha_required' makes the upload page show the Turnstile check, get a pass from upload-pass and retry.
  v_mode := coalesce((select order_captcha from public.app_settings where id = 1), 'auto');
  if v_mode = 'always' or (v_mode = 'auto' and (
       (v_ip is not null and (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 3)
       or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 20)) then
    if p_pass is null then raise exception 'captcha_required'; end if;
    delete from public.upload_pass up where up.created_at < now() - interval '1 hour';
    delete from public.upload_pass up where up.id = p_pass and up.created_at > now() - interval '10 minutes';
    if not found then raise exception 'captcha_required'; end if;
  end if;

  -- File checks: only print-able types, real sizes, each file up to 50 MB, the order up to the plan's size.
  v_max := public.plan_order_bytes(v_shop);
  for v_f in select * from jsonb_array_elements(p_files) loop
    v_ext := lower(substring(coalesce(v_f->>'name', '') from '\.([A-Za-z0-9]+)$'));
    v_mime := public.upload_mime_for(v_ext);
    if v_mime is null or coalesce(v_f->>'mime', '') <> v_mime then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    if v_f->>'kind' = 'idcard' and v_mime <> 'application/pdf' then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    v_size := coalesce((v_f->>'size')::bigint, 0);
    if v_size < 1 or v_size > 52428800 then raise exception 'Each file must be under 50 MB'; end if;
    v_bytes := v_bytes + v_size;
  end loop;
  if v_bytes > v_max then raise exception 'This shop accepts up to % MB per order', v_max / 1048576; end if;

  -- v25: storage budgets (files not yet auto-deleted), so a flood of uploads cannot fill the storage for everyone.
  v_cap_shop := public.shop_storage_bytes(v_shop);
  v_cap_all := public.storage_budget_bytes();
  select coalesce(sum(f.size_bytes), 0) into v_live_shop
    from public.order_files f join public.orders o on o.id = f.order_id
    where o.shop_id = v_shop.id and o.files_deleted = false;
  if v_live_shop + v_bytes > v_cap_shop then
    raise exception 'This shop''s file space is full right now. Please ask the shop to finish or clear old orders, then try again.';
  end if;
  select coalesce(sum(f.size_bytes), 0) into v_live_all
    from public.order_files f join public.orders o on o.id = f.order_id
    where o.files_deleted = false;
  if v_live_all + v_bytes > v_cap_all then
    raise exception 'Uploads are paused for a short while because the service is very busy. Please try again later.';
  end if;
  if v_ip is not null then insert into public.order_rate (ip_hash) values (v_ip); end if;
  v_pro := public.is_pro(v_shop);
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'passport') then
    raise exception 'Passport photo sheet is not available at this shop';
  end if;
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'idcard') then
    raise exception 'ID card sheet is not available at this shop';
  end if;

  if p_counter is not null then
    select c.id, c.name into v_counter_id, v_counter_name
      from public.counters c where c.id = p_counter and c.shop_id = v_shop.id
        and (v_pro or c.id in (
          select c2.id from public.counters c2 where c2.shop_id = v_shop.id
          order by c2.created_at, c2.id limit public.free_counter_limit()));
  end if;

  select coalesce(max(o.token), 0) + 1 into v_token
    from public.orders o where o.shop_id = v_shop.id and o.created_at >= v_day_start;

  insert into public.orders (shop_id, token, customer_name, note, counter_id, counter_name)
    values (v_shop.id, v_token, nullif(left(trim(coalesce(p_customer_name,'')), 60), ''),
      nullif(left(trim(coalesce(p_note,'')), 300), ''), v_counter_id, v_counter_name)
    returning * into v_order;
  if v_ip is not null then
    insert into public.order_senders (order_id, shop_id, ip_hash) values (v_order.id, v_shop.id, v_ip);
  end if;

  for v_f in select * from jsonb_array_elements(p_files) loop
    v_i := v_i + 1;
    v_kind := case when v_f->>'kind' in ('passport', 'idcard') then v_f->>'kind' else 'print' end;
    v_binding := false;
    v_lam := false;
    if v_kind = 'passport' then
      v_photos := greatest(1, least(300, coalesce((v_f->>'photos')::int, 8)));
      v_pages := ceil(v_photos / 30.0)::int;
      v_total_pages := v_pages;
      v_copies := 1;
      v_color := true;
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40);
      v_price := round(v_pages * v_copies * v_rate, 2);
    elsif v_kind = 'idcard' then
      -- One A4 page (front above back). finalize-order checks the PDF really has one page.
      v_photos := null;
      v_pages := 1;
      v_total_pages := 1;
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, true);
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'idcard_sheet')::numeric, 20);
      v_price := round(v_copies * v_rate, 2);
    else
      v_photos := null;
      v_pages := greatest(1, least(2000, coalesce((v_f->>'pages_to_print')::int, 1)));
      v_total_pages := greatest(1, least(2000, coalesce((v_f->>'total_pages')::int, 1)));
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, false);
      v_duplex := coalesce((v_f->>'duplex')::boolean, false);
      -- Extras only when the shop has a rate for them (0 / missing = not offered).
      v_binding := coalesce((v_f->>'binding')::boolean, false) and coalesce((v_shop.rates ->> 'binding')::numeric, 0) > 0;
      v_lam := coalesce((v_f->>'lamination')::boolean, false) and coalesce((v_shop.rates ->> 'lamination')::numeric, 0) > 0;
      v_range := nullif(left(v_f->>'page_range', 60), '');
      v_price := public.file_price(v_shop.rates, v_pages, v_copies, v_color, v_duplex, v_binding, v_lam);
    end if;
    v_total := v_total + v_price;
    v_path := v_shop.id::text || '/' || v_order.id::text || '/' || v_i::text || '-' ||
      left(regexp_replace(coalesce(v_f->>'name','file'), '[^A-Za-z0-9._-]', '_', 'g'), 80);
    v_paths := v_paths || v_path;
    insert into public.order_files (order_id, shop_id, storage_path, file_name, mime, size_bytes,
        total_pages, page_range, pages_to_print, copies, color, duplex, price, item_kind, photos, binding, lamination)
      values (v_order.id, v_shop.id, v_path, left(coalesce(v_f->>'name','file'), 200), v_f->>'mime',
        (v_f->>'size')::bigint, v_total_pages, v_range, v_pages, v_copies, v_color, v_duplex, v_price,
        v_kind, v_photos, v_binding, v_lam);
  end loop;

  update public.orders set total = v_total where id = v_order.id;

  return query select v_order.id, v_order.access_key, v_token, v_shop.id, v_total, v_paths;
end $$;
grant execute on function public.create_order(text, text, text, jsonb, uuid, uuid) to anon, authenticated;

-- ============ 4. Block sender (owner or staff of the order's shop) ============
create or replace function public.can_manage_shop(p_shop uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.shops s where s.id = p_shop and s.owner_id = auth.uid())
      or p_shop in (select public.staff_shop_ids());
$$;
revoke all on function public.can_manage_shop(uuid) from public, anon;
grant execute on function public.can_manage_shop(uuid) to authenticated;

-- Blocks the order's network for this shop and cancels its open orders. Returns how many were cancelled
-- (-1 when the order has no network id, e.g. a reorder or an old order).
create or replace function public.block_order_sender(p_order_id uuid)
returns int language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid;
  v_ip text;
  v_n int;
begin
  select o.shop_id into v_shop from public.orders o where o.id = p_order_id;
  if v_shop is null or not public.can_manage_shop(v_shop) then raise exception 'not allowed'; end if;
  select s.ip_hash into v_ip from public.order_senders s where s.order_id = p_order_id;
  if v_ip is null then return -1; end if;
  insert into public.shop_blocked_senders (shop_id, ip_hash) values (v_shop, v_ip) on conflict do nothing;
  update public.orders o set status = 'cancelled', updated_at = now()
    where o.shop_id = v_shop and o.status in ('received', 'printing')
      and o.id in (select s.order_id from public.order_senders s where s.shop_id = v_shop and s.ip_hash = v_ip);
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.block_order_sender(uuid) from public, anon;
grant execute on function public.block_order_sender(uuid) to authenticated;

create or replace function public.blocked_sender_count(p_shop uuid)
returns int language plpgsql stable security definer set search_path = public as $$
begin
  if not public.can_manage_shop(p_shop) then raise exception 'not allowed'; end if;
  return (select count(*) from public.shop_blocked_senders b where b.shop_id = p_shop);
end $$;
revoke all on function public.blocked_sender_count(uuid) from public, anon;
grant execute on function public.blocked_sender_count(uuid) to authenticated;

create or replace function public.unblock_all_senders(p_shop uuid)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  if not exists (select 1 from public.shops s where s.id = p_shop and s.owner_id = auth.uid()) then raise exception 'not allowed'; end if;
  delete from public.shop_blocked_senders b where b.shop_id = p_shop;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.unblock_all_senders(uuid) from public, anon;
grant execute on function public.unblock_all_senders(uuid) to authenticated;

-- ============ 5. finalize attempts ============
alter table public.orders add column if not exists finalize_attempts int not null default 0;

create or replace function public.finalize_begin(p_order_id uuid, p_key uuid)
returns int language plpgsql security definer set search_path = public as $$
declare v_n int;
begin
  update public.orders o set finalize_attempts = o.finalize_attempts + 1
    where o.id = p_order_id and o.access_key = p_key and o.status = 'uploading'
      and o.created_at > now() - interval '35 minutes'
    returning o.finalize_attempts into v_n;
  return coalesce(v_n, 0);
end $$;
revoke all on function public.finalize_begin(uuid, uuid) from public, anon, authenticated;
grant execute on function public.finalize_begin(uuid, uuid) to service_role;

-- ============ 6. monitoring ============
create table if not exists public.ops_events (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  source text not null,
  level text not null default 'error',
  message text not null
);
create index if not exists ops_events_created_idx on public.ops_events (created_at);
alter table public.ops_events enable row level security;
revoke all on public.ops_events from anon, authenticated;
grant select, insert, delete on public.ops_events to service_role;

-- What the Health check workflow reads (service role only). p_since_min: how far back to look for events.
create or replace function public.ops_health(p_since_min int default 20)
returns jsonb language plpgsql volatile security definer set search_path = public, storage, cron as $$
declare
  v_events jsonb;
  v_cron int := 0;
begin
  select coalesce(jsonb_agg(jsonb_build_object('source', x.source, 'level', x.level, 'n', x.n, 'last', x.last)), '[]'::jsonb)
    into v_events
    from (select e.source, e.level, count(*) as n, (array_agg(e.message order by e.id desc))[1] as last
          from public.ops_events e where e.created_at > now() - make_interval(mins => p_since_min)
          group by e.source, e.level) x;
  begin
    select count(*) into v_cron from cron.job_run_details d
      where d.status = 'failed' and d.start_time > now() - make_interval(mins => p_since_min);
  exception when others then v_cron := 0;
  end;
  delete from public.ops_events where created_at < now() - interval '30 days';
  return jsonb_build_object(
    'events', v_events,
    'cron_failed', v_cron,
    'uploads_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'uploads'),
    'storage_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o),
    'db_bytes', pg_database_size(current_database()),
    'cleanup_overdue', (select count(*) from public.orders o join public.shops s on s.id = o.shop_id
        where o.files_deleted = false and o.status in ('ready', 'done', 'cancelled')
          and o.created_at < now() - make_interval(hours => public.shop_file_hours(s)) - interval '2 hours'),
    'stuck_uploading', (select count(*) from public.orders o
        where o.status = 'uploading' and o.files_deleted = false and o.created_at < now() - interval '2 hours')
  );
end $$;
revoke all on function public.ops_health(int) from public, anon, authenticated;
grant execute on function public.ops_health(int) to service_role;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-22-v26-phone-login.sql
-- ======================================================================
-- PrintQR v26 migration (2026-11-22): mobile-number (OTP) logins in the admin panel. Safe to run more than once. Needs v25.
--
-- Accounts made with "Continue with mobile" have no email, only auth.users.phone ("919876543210").
-- admin_users and admin_payments now show "+919876543210" where the email would be, admin_users can be
-- searched by number, and a phone-confirmed account no longer shows as "unconfirmed".
-- Same function signatures as before (create or replace), so nothing else changes.

create or replace function public.admin_users(p_q text default '', p_limit int default 50, p_offset int default 0)
returns table (user_id uuid, email text, created_at timestamptz, last_sign_in_at timestamptz,
  confirmed boolean, banned boolean, shop_id uuid, shop_name text, is_admin boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return query
  select u.id, coalesce(nullif(u.email, '')::text, '+' || nullif(u.phone, '')::text), u.created_at, u.last_sign_in_at,
    (u.email_confirmed_at is not null or u.phone_confirmed_at is not null), coalesce(u.banned_until > now(), false),
    s.id, s.name, exists (select 1 from public.admins a where a.user_id = u.id)
  from auth.users u left join public.shops s on s.owner_id = u.id
  where coalesce(p_q, '') = '' or u.email ilike '%' || p_q || '%' or coalesce(s.name, '') ilike '%' || p_q || '%'
    or (length(regexp_replace(p_q, '\D', '', 'g')) >= 4 and coalesce(u.phone, '') like '%' || regexp_replace(p_q, '\D', '', 'g') || '%')
  order by u.created_at desc
  limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
end $$;
revoke all on function public.admin_users(text, int, int) from public, anon;
grant execute on function public.admin_users(text, int, int) to authenticated;

create or replace function public.admin_payments()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'subs', coalesce((select jsonb_agg(x order by x.plan_expires_at desc nulls last) from (
      select s.id as shop_id, s.name, coalesce(nullif(u.email, '')::text, '+' || nullif(u.phone, '')::text) as email,
        s.plan, s.plan_period, s.subscription_status,
        s.plan_expires_at, s.razorpay_subscription_id as sub_id, public.is_pro(s) as is_pro
      from public.shops s left join auth.users u on u.id = s.owner_id
      where s.razorpay_subscription_id is not null) x), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(e order by e.received_at desc) from (
      select event, received_at from public.billing_events order by received_at desc limit 30) e), '[]'::jsonb)
  );
end $$;
revoke all on function public.admin_payments() from public, anon;
grant execute on function public.admin_payments() to authenticated;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-22-v27-login-design.sql
-- ======================================================================
-- v27: admin picks the login page design (website, Android app, desktop app read it at runtime).
alter table public.app_settings add column if not exists login_design text not null default 'classic';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'app_settings_login_design_check') then
    alter table public.app_settings add constraint app_settings_login_design_check check (login_design in ('classic', 'modern'));
  end if;
end $$;

create or replace function public.get_app_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'announcement', s.announcement, 'announcement_hi', s.announcement_hi,
    'maintenance', s.maintenance, 'maintenance_msg', s.maintenance_msg,
    'min_app_version', s.min_app_version, 'free_counter_limit', s.free_counter_limit,
    'login_design', s.login_design)
  from public.app_settings s where s.id = 1;
$$;
grant execute on function public.get_app_settings() to anon, authenticated;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    -- an older admin page sends no login_design: keep the current one
    login_design     = case when p->>'login_design' in ('classic', 'modern') then p->>'login_design' else login_design end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;

-- ======================================================================
-- migrations/2026-11-22-v28-login-design-per-platform.sql
-- ======================================================================
-- v28: login page design per platform. login_designs = {"app":..,"mweb":..,"web":..,"desktop":..}
-- (each 'classic' or 'modern'); a missing key falls back to login_design (v27).
alter table public.app_settings add column if not exists login_designs jsonb not null default '{}'::jsonb;

create or replace function public.get_app_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'announcement', s.announcement, 'announcement_hi', s.announcement_hi,
    'maintenance', s.maintenance, 'maintenance_msg', s.maintenance_msg,
    'min_app_version', s.min_app_version, 'free_counter_limit', s.free_counter_limit,
    'login_design', s.login_design, 'login_designs', s.login_designs)
  from public.app_settings s where s.id = 1;
$$;
grant execute on function public.get_app_settings() to anon, authenticated;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  k text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) in ('classic', 'modern') then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when p->>'login_design' in ('classic', 'modern') then p->>'login_design' else login_design end,
    -- an older admin page sends no login_designs: keep the current ones
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;

-- ======================================================================
-- migrations/2026-11-22-v29-login-designs-more.sql
-- ======================================================================
-- v29: three more login designs for computers: split (lime side panel), bento (card + tiles), bentofull (full-screen tiles).
alter table public.app_settings drop constraint if exists app_settings_login_design_check;
alter table public.app_settings add constraint app_settings_login_design_check
  check (login_design in ('classic', 'modern', 'split', 'bento', 'bentofull'));

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  v_ok text[] := array['classic', 'modern', 'split', 'bento', 'bentofull'];
  k text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) = any(v_ok) then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when (p->>'login_design') = any(v_ok) then p->>'login_design' else login_design end,
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;

-- ======================================================================
-- migrations/2026-11-22-v30-health-alerts.sql
-- ======================================================================
-- PrintQR v30 (2026-11-22): health check from Supabase itself every 15 minutes (pg_cron + pg_net),
-- because GitHub's schedule runs it only a few times a day. Problems are kept in public.ops_alerts,
-- shown in the Admin panel and sent as a push notification to every admin's phones / browsers.
-- The "Health check" GitHub workflow stays as a backup (it also notices when Supabase itself is down).
-- Safe to run more than once. Needs v4 (pg_cron, pg_net, private.cron_tokens), v14 (push_tokens), v25 (ops_health).

alter table public.app_settings add column if not exists storage_limit_mb int not null default 1024;  -- Supabase Free; Pro = 102400
alter table public.app_settings add column if not exists db_limit_mb int not null default 500;         -- Supabase Free; Pro = 8192
alter table public.app_settings add column if not exists health_checked_at timestamptz;

create table if not exists public.ops_alerts (
  id bigint generated always as identity primary key,
  key text not null,
  title text not null,
  detail text not null default '',
  opened_at timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  notified_at timestamptz,
  closed_at timestamptz
);
create unique index if not exists ops_alerts_one_open on public.ops_alerts (key) where closed_at is null;
create index if not exists ops_alerts_time on public.ops_alerts (opened_at desc);
alter table public.ops_alerts enable row level security;  -- no policies: admins read through admin_alerts()
revoke all on public.ops_alerts from public, anon, authenticated;
grant select, insert, update, delete on public.ops_alerts to service_role;
grant select, update on public.app_settings to service_role;
grant select on public.push_tokens to service_role;
grant select on public.admins to service_role;

-- Admin panel (bell): last check time + open problems + problems fixed in the last 30 days (max 50).
create or replace function public.admin_alerts()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'checked_at', (select health_checked_at from public.app_settings where id = 1),
    'alerts', coalesce((select jsonb_agg(jsonb_build_object('key', a.key, 'title', a.title, 'detail', a.detail,
        'opened_at', a.opened_at, 'last_seen', a.last_seen, 'closed_at', a.closed_at) order by a.closed_at nulls first, a.opened_at desc)
      from (select * from public.ops_alerts where closed_at is null or closed_at > now() - interval '30 days' order by closed_at nulls first, opened_at desc limit 50) a), '[]'::jsonb)
  );
end $$;
revoke all on function public.admin_alerts() from public, anon;
grant execute on function public.admin_alerts() to authenticated;

delete from public.ops_alerts where closed_at < now() - interval '60 days';

insert into private.cron_tokens (name, token)
values ('health', encode(extensions.gen_random_bytes(32), 'hex'))
on conflict (name) do nothing;

do $$
begin
  if exists (select 1 from cron.job where jobname = 'printqr-health') then
    perform cron.unschedule('printqr-health');
  end if;
end $$;

select cron.schedule(
  'printqr-health',
  '*/15 * * * *',
  $job$
  select net.http_post(
    url := 'https://asqgdgzxkdksoikmffmd.supabase.co/functions/v1/health-check',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-token', (select token from private.cron_tokens where name = 'health')
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 60000
  );
  $job$
);

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-23-v31-landing-design.sql
-- ======================================================================
-- v31: landing (home) page design, chosen by the admin like the login design (v27-v29).
-- landing_design = general choice; landing_designs = {"app":..,"mweb":..,"web":..,"desktop":..} per platform
-- (a missing key falls back to landing_design). Values: 'classic' (current page) or 'duo' (two panels).
-- Safe to run more than once.
alter table public.app_settings add column if not exists landing_design text not null default 'classic';
alter table public.app_settings add column if not exists landing_designs jsonb not null default '{}'::jsonb;
alter table public.app_settings drop constraint if exists app_settings_landing_design_check;
alter table public.app_settings add constraint app_settings_landing_design_check
  check (landing_design in ('classic', 'duo'));

create or replace function public.get_app_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'announcement', s.announcement, 'announcement_hi', s.announcement_hi,
    'maintenance', s.maintenance, 'maintenance_msg', s.maintenance_msg,
    'min_app_version', s.min_app_version, 'free_counter_limit', s.free_counter_limit,
    'login_design', s.login_design, 'login_designs', s.login_designs,
    'landing_design', s.landing_design, 'landing_designs', s.landing_designs)
  from public.app_settings s where s.id = 1;
$$;
grant execute on function public.get_app_settings() to anon, authenticated;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  v_ok text[] := array['classic', 'modern', 'split', 'bento', 'bentofull'];
  v_land jsonb := '{}'::jsonb;
  v_land_ok text[] := array['classic', 'duo'];
  k text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) = any(v_ok) then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  if jsonb_typeof(p->'landing_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'landing_designs'->>k) = any(v_land_ok) then
        v_land := v_land || jsonb_build_object(k, p->'landing_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when (p->>'login_design') = any(v_ok) then p->>'login_design' else login_design end,
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    -- an older admin page sends no landing fields: keep the current ones
    landing_design   = case when (p->>'landing_design') = any(v_land_ok) then p->>'landing_design' else landing_design end,
    landing_designs  = case when jsonb_typeof(p->'landing_designs') = 'object' then v_land else landing_designs end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;

