-- ======================================================================
-- migrations/2026-11-23-v33-billing-payments.sql
-- ======================================================================
-- PrintQR v33 (2026-11-23): one row per Razorpay payment, so owners can see and download a receipt
-- for every charge (Dashboard -> Plan -> Payments / receipts).
-- Written only by the Edge Functions (service role): razorpay-webhook on subscription.charged and
-- verify-payment after checkout. payment_id is unique, so repeats of the same payment are ignored.
-- Owners can read their own shop's rows. Safe to run more than once.

create table if not exists public.billing_payments (
  payment_id text primary key,       -- Razorpay pay_... id (unique)
  shop_id uuid not null references public.shops(id) on delete cascade,
  subscription_id text,
  tier text not null default 'pro' check (tier in ('pro', 'plus')),
  period text check (period in ('monthly', 'yearly')),
  amount int not null check (amount >= 0),          -- in paise (4900 = Rs 49)
  currency text not null default 'INR',
  paid_at timestamptz not null default now(),
  period_start timestamptz,
  period_end timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists billing_payments_shop on public.billing_payments(shop_id, paid_at desc);

alter table public.billing_payments enable row level security;
drop policy if exists "owner reads payments" on public.billing_payments;
create policy "owner reads payments" on public.billing_payments for select to authenticated
  using (shop_id in (select id from public.shops where owner_id = auth.uid()));

revoke all on public.billing_payments from public, anon, authenticated;
grant select on public.billing_payments to authenticated;
grant select, insert, update, delete on public.billing_payments to service_role;

-- ======================================================================
-- migrations/2026-11-23-v34-upi-paid-file-reports.sql
-- ======================================================================
-- PrintQR v34 migration (2026-11-23): UPI "Paid" mark (item 16) + "Report file" and takedown hold (item 17).
-- Safe to run more than once. Needs v25.
--
-- 1. orders.paid_at / paid_by: the shop marks an order Paid / Unpaid with set_order_paid() (owner or staff).
--    get_order_status() also returns paid, so the customer's page shows "Paid ✓".
-- 2. orders.hold: a reported order. Its files are kept (cleanup skips it), the shop cannot open or delete
--    them any more, and it cannot be printed again. Only an admin ends the hold (admin-action:
--    report_dismiss / report_delete_files). See docs/takedown-sop.md.
-- 3. file_reports: one row per report (owner / staff of the shop insert and read their own, admins read all).
--    report_order_files() is what the dashboard calls.

-- ============ columns ============
alter table public.orders add column if not exists paid_at timestamptz;
alter table public.orders add column if not exists paid_by uuid references auth.users (id) on delete set null;
alter table public.orders add column if not exists hold boolean not null default false;
create index if not exists orders_hold_idx on public.orders (id) where hold;

-- ============ 1. Paid / Unpaid ============
-- Owners / staff may only update status, updated_at and files_deleted on orders, so this runs as definer.
create or replace function public.set_order_paid(p_order_id uuid, p_paid boolean)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid;
  v_at timestamptz;
begin
  select o.shop_id into v_shop from public.orders o where o.id = p_order_id;
  if v_shop is null or not public.can_manage_shop(v_shop) then raise exception 'not allowed'; end if;
  update public.orders o
    set paid_at = case when coalesce(p_paid, false) then coalesce(o.paid_at, now()) end,
        paid_by = case when coalesce(p_paid, false) then coalesce(o.paid_by, auth.uid()) end
    where o.id = p_order_id
    returning o.paid_at into v_at;
  return v_at;
end $$;
revoke all on function public.set_order_paid(uuid, boolean) from public, anon;
grant execute on function public.set_order_paid(uuid, boolean) to authenticated;

-- Customer status page: same as v17 plus paid (the return type changes, so drop and create).
drop function if exists public.get_order_status(uuid, uuid);
create function public.get_order_status(p_order_id uuid, p_key uuid)
returns table (token int, status text, total numeric, created_at timestamptz, shop_name text, upi_id text, file_count int,
  files_deleted boolean, files_expire_at timestamptz, is_plus boolean, logo_url text, brand_color text, paid boolean)
language sql stable security definer set search_path = public as $$
  select o.token, o.status, o.total, o.created_at, s.name, s.upi_id,
    (select count(*)::int from public.order_files f where f.order_id = o.id),
    o.files_deleted,
    o.created_at + make_interval(hours => public.shop_file_hours(s)),
    public.is_plus(s),
    case when public.is_plus(s) then s.logo_url end,
    case when public.is_plus(s) then s.brand_color end,
    o.paid_at is not null
  from public.orders o join public.shops s on s.id = o.shop_id
  where o.id = p_order_id and o.access_key = p_key;
$$;
grant execute on function public.get_order_status(uuid, uuid) to anon, authenticated;

-- ============ 2. hold: keep reported files ============
-- Cleanup: same as v25, but held (reported) orders keep their files until an admin decides.
create or replace function public.cleanup_candidates()
returns table (order_id uuid, status text, paths text[])
language sql stable security definer set search_path = public as $$
  select o.id, o.status, array(select f.storage_path from public.order_files f where f.order_id = o.id)
  from public.orders o join public.shops s on s.id = o.shop_id
  where o.files_deleted = false and not o.hold and (
    (o.status = 'uploading' and o.created_at < now() - interval '35 minutes')
    or (o.status in ('ready', 'done', 'cancelled') and o.created_at < now() - make_interval(hours => public.shop_file_hours(s)))
    or (o.status in ('received', 'printing')
        and o.created_at < now() - make_interval(hours => greatest(public.shop_file_hours(s), 48)))
  )
  limit 500;
$$;
revoke all on function public.cleanup_candidates() from public, anon, authenticated;
grant execute on function public.cleanup_candidates() to service_role;

-- Is this storage object ('<shop>/<order>/<file>') part of a held order?
create or replace function public.upload_held(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select case when split_part(coalesce(p_name, ''), '/', 2) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    then exists (select 1 from public.orders o where o.id = split_part(p_name, '/', 2)::uuid and o.hold)
    else false end;
$$;
revoke all on function public.upload_held(text) from public;
grant execute on function public.upload_held(text) to authenticated;

-- Shop owner / staff can no longer open or delete the files of a held order (admins use the service role).
drop policy if exists "owner reads uploads" on storage.objects;
create policy "owner reads uploads" on storage.objects for select to authenticated
  using (bucket_id = 'uploads' and (storage.foldername(name))[1] in (select id::text from public.shops where owner_id = auth.uid())
    and not public.upload_held(name));
drop policy if exists "owner deletes uploads" on storage.objects;
create policy "owner deletes uploads" on storage.objects for delete to authenticated
  using (bucket_id = 'uploads' and (storage.foldername(name))[1] in (select id::text from public.shops where owner_id = auth.uid())
    and not public.upload_held(name));
drop policy if exists "staff reads uploads" on storage.objects;
create policy "staff reads uploads" on storage.objects for select to authenticated
  using (bucket_id = 'uploads' and (storage.foldername(name))[1] in (select x::text from public.staff_shop_ids() x)
    and not public.upload_held(name));
drop policy if exists "staff deletes uploads" on storage.objects;
create policy "staff deletes uploads" on storage.objects for delete to authenticated
  using (bucket_id = 'uploads' and (storage.foldername(name))[1] in (select x::text from public.staff_shop_ids() x)
    and not public.upload_held(name));

-- A signed-in shop login cannot mark a held order's files as deleted (the service role and admins can).
create or replace function public.orders_hold_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if old.hold and new.files_deleted and not old.files_deleted and auth.uid() is not null and not public.is_admin() then
    raise exception 'This order is under review. Its files are kept.';
  end if;
  return new;
end $$;
drop trigger if exists orders_hold_guard on public.orders;
create trigger orders_hold_guard before update of files_deleted on public.orders
  for each row execute function public.orders_hold_guard();

-- "Print again" (v23): not for a held order.
create or replace function public.reorder_info(p_order_id uuid, p_key uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_order public.orders;
  v_shop public.shops;
  v_pro boolean;
begin
  select * into v_order from public.orders o where o.id = p_order_id and o.access_key = p_key;
  if not found then raise exception 'Order not found'; end if;
  select * into v_shop from public.shops s where s.id = v_order.shop_id;
  v_pro := public.is_pro(v_shop);
  return jsonb_build_object(
    'can', not v_order.files_deleted and not v_order.hold and v_order.status in ('received', 'printing', 'ready', 'done')
           and v_shop.is_open and not v_shop.blocked,
    'is_open', v_shop.is_open and not v_shop.blocked,
    'rates', case when v_pro then jsonb_build_object('passport_sheet', 40, 'idcard_sheet', 20) || v_shop.rates
                  else v_shop.rates - 'passport_sheet' - 'idcard_sheet' end,
    'files', case when v_order.files_deleted or v_order.hold then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', f.id, 'file_name', f.file_name, 'item_kind', f.item_kind, 'pages', f.pages_to_print,
          'copies', f.copies, 'color', f.color, 'duplex', f.duplex, 'binding', f.binding,
          'lamination', f.lamination, 'photos', f.photos,
          'allowed', f.item_kind = 'print' or v_pro)
        order by coalesce(substring(f.storage_path from '/([0-9]+)-[^/]*$')::int, 0), f.id)
      from public.order_files f where f.order_id = v_order.id), '[]'::jsonb) end
  );
end $$;
revoke all on function public.reorder_info(uuid, uuid) from public;
grant execute on function public.reorder_info(uuid, uuid) to anon, authenticated;

-- reorder() copies files by order_files.source_path: refuse a copy of a held order's file.
create or replace function public.order_files_hold_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.source_path is not null and exists (
      select 1 from public.order_files f join public.orders o on o.id = f.order_id
      where f.storage_path = new.source_path and o.hold) then
    raise exception 'This order cannot be printed again';
  end if;
  return new;
end $$;
drop trigger if exists order_files_hold_guard on public.order_files;
create trigger order_files_hold_guard before insert on public.order_files
  for each row execute function public.order_files_hold_guard();

-- ============ 3. file reports ============
create table if not exists public.file_reports (
  id bigint generated always as identity primary key,
  -- Kept when the order or shop row is removed later (the report is the record).
  order_id uuid references public.orders (id) on delete set null,
  shop_id uuid references public.shops (id) on delete set null,
  reporter_id uuid references auth.users (id) on delete set null,
  reason text not null check (reason in ('csam', 'illegal', 'violence', 'copyright', 'privacy', 'other')),
  note text check (note is null or char_length(note) <= 500),
  -- Filled from the order when the report is made (for the admin list and the record).
  token int,
  shop_name text,
  file_names text[] not null default '{}',
  paths text[] not null default '{}',
  status text not null default 'open' check (status in ('open', 'dismissed', 'files_deleted')),
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  resolved_by uuid references auth.users (id) on delete set null
);
create index if not exists file_reports_status_idx on public.file_reports (status, created_at desc);
create index if not exists file_reports_order_idx on public.file_reports (order_id);
create index if not exists file_reports_shop_idx on public.file_reports (shop_id, created_at desc);
alter table public.file_reports enable row level security;
revoke all on public.file_reports from public, anon, authenticated;
grant select on public.file_reports to authenticated;
grant insert (order_id, reason, note) on public.file_reports to authenticated;
grant select, insert, update on public.file_reports to service_role;

drop policy if exists "shop inserts file reports" on public.file_reports;
create policy "shop inserts file reports" on public.file_reports for insert to authenticated
  with check (shop_id is not null and public.can_manage_shop(shop_id) and reporter_id = auth.uid());
drop policy if exists "shop reads own file reports" on public.file_reports;
create policy "shop reads own file reports" on public.file_reports for select to authenticated
  using (reporter_id = auth.uid() or (shop_id is not null and public.can_manage_shop(shop_id)));
drop policy if exists "admin reads file reports" on public.file_reports;
create policy "admin reads file reports" on public.file_reports for select to authenticated
  using (public.is_admin());

-- Every new report (also a direct insert): check the caller, fill the order details, put the order on hold.
create or replace function public.file_reports_fill()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_order public.orders;
begin
  if auth.uid() is null then raise exception 'not allowed'; end if;
  select * into v_order from public.orders o where o.id = new.order_id;
  if not found or not public.can_manage_shop(v_order.shop_id) then raise exception 'not allowed'; end if;
  if new.reason is null or new.reason not in ('csam', 'illegal', 'violence', 'copyright', 'privacy', 'other') then
    raise exception 'Please choose a reason';
  end if;
  if v_order.files_deleted then raise exception 'These files are already deleted, so they cannot be reported'; end if;
  if (select count(*) from public.file_reports r where r.shop_id = v_order.shop_id and r.created_at > now() - interval '1 day') >= 20 then
    raise exception 'Too many reports. Please try again tomorrow.';
  end if;
  new.shop_id := v_order.shop_id;
  new.reporter_id := auth.uid();
  new.note := left(nullif(trim(coalesce(new.note, '')), ''), 500);
  new.token := v_order.token;
  new.shop_name := (select s.name from public.shops s where s.id = v_order.shop_id);
  new.file_names := array(select f.file_name from public.order_files f where f.order_id = v_order.id order by f.storage_path);
  new.paths := array(select f.storage_path from public.order_files f where f.order_id = v_order.id order by f.storage_path);
  new.status := 'open';
  new.created_at := now();
  new.resolved_at := null;
  new.resolved_by := null;
  update public.orders o set hold = true where o.id = v_order.id;
  return new;
end $$;
drop trigger if exists file_reports_fill on public.file_reports;
create trigger file_reports_fill before insert on public.file_reports
  for each row execute function public.file_reports_fill();

-- Dashboard "Report file": holds the order and records the report. Returns the report id.
create or replace function public.report_order_files(p_order_id uuid, p_reason text, p_note text default null)
returns bigint language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid;
  v_id bigint;
begin
  select o.shop_id into v_shop from public.orders o where o.id = p_order_id;
  if v_shop is null or not public.can_manage_shop(v_shop) then raise exception 'not allowed'; end if;
  insert into public.file_reports (order_id, reason, note) values (p_order_id, p_reason, p_note) returning id into v_id;
  update public.orders o set hold = true where o.id = p_order_id;
  return v_id;
end $$;
revoke all on function public.report_order_files(uuid, text, text) from public, anon;
grant execute on function public.report_order_files(uuid, text, text) to authenticated;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-23-v35-my-sessions.sql
-- ======================================================================
-- PrintQR v35 (2026-11-23): "Logged-in devices" in Settings. A shop owner or staff login can see where
-- their account is signed in (device, when last used, a masked IP) and log out one device.
-- "Log out all other devices" uses Supabase Auth itself (signOut scope 'others'), not this file.
-- Ending a session deletes its row in auth.sessions (its refresh tokens go with it), so that device
-- cannot refresh again; its current access token still works until it expires (about an hour at most).
-- Safe to run more than once.

-- Signed-in devices of the caller, newest first. is_current = the session this request comes from.
create or replace function public.my_sessions()
returns table (id uuid, created_at timestamptz, last_active timestamptz, user_agent text, ip text, is_current boolean)
language plpgsql stable security definer set search_path = public, auth as $$
declare
  v_uid uuid := auth.uid();
  v_sid text := nullif(auth.jwt() ->> 'session_id', '');
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  return query
    select s.id,
           s.created_at,
           coalesce(s.refreshed_at::timestamptz, s.updated_at, s.created_at) as last_active,
           left(coalesce(s.user_agent, ''), 300) as user_agent,
           case
             when s.ip is null then null
             when family(s.ip) = 4 then split_part(host(s.ip), '.', 1) || '.' || split_part(host(s.ip), '.', 2) || '.x.x'
             else split_part(host(s.ip), ':', 1) || ':' || split_part(host(s.ip), ':', 2) || ':x:x'
           end as ip,
           (v_sid is not null and s.id::text = v_sid) as is_current
    from auth.sessions s
    where s.user_id = v_uid
      and (s.not_after is null or s.not_after > now())
    order by (v_sid is not null and s.id::text = v_sid) desc, 3 desc
    limit 50;
end $$;
revoke all on function public.my_sessions() from public, anon;
grant execute on function public.my_sessions() to authenticated;

-- Log out one of the caller's other devices. The current session is refused (the app logs out normally).
-- Returns false when that session is already gone.
create or replace function public.end_my_session(p_id uuid)
returns boolean language plpgsql volatile security definer set search_path = public, auth as $$
declare
  v_uid uuid := auth.uid();
  v_sid text := nullif(auth.jwt() ->> 'session_id', '');
  v_n int;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if p_id is null then return false; end if;
  if v_sid is not null and p_id::text = v_sid then raise exception 'use log out for this device'; end if;
  delete from auth.sessions s where s.id = p_id and s.user_id = v_uid;
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;
revoke all on function public.end_my_session(uuid) from public, anon;
grant execute on function public.end_my_session(uuid) to authenticated;

-- ======================================================================
-- migrations/2026-11-23-v36-admin-mfa.sql
-- ======================================================================
-- PrintQR v36 (2026-11-23): 2-step login (TOTP, Supabase Auth MFA) for the admin panel (audit S7).
--
-- What changes:
--  * is_admin() is now true only when the caller is in public.admins AND the login is aal2
--    (auth.jwt()->>'aal' = 'aal2', i.e. the 6-digit authenticator code was entered in this session).
--    Every admin_* function already starts with `if not public.is_admin() then raise exception 'not allowed'`,
--    so all of them require aal2 without being rewritten. The admin-action Edge Function checks the same.
--  * admin_status(): tells the app "is this login an admin at all" (without the aal check), whether 2-step is
--    required, and the current aal. The Dashboard drawer link and the /admin page use it to show the
--    "Set up 2-step login" / "Enter code" screen instead of "Not allowed".
--  * app_settings.admin_mfa_required (default TRUE). admin_set_settings() does not touch it, so only the
--    SQL editor can change it.
--
-- Before the first visit: Supabase Dashboard -> Authentication -> Multi-Factor (MFA) -> TOTP (App Authenticator)
-- must be enabled. Then open #/admin, scan the QR code with Google Authenticator / Authy / Microsoft Authenticator
-- and type the 6-digit code once. Every later admin login asks only for the code.
--
-- EMERGENCY (lost phone, TOTP turned off by mistake, locked out): in Supabase -> SQL Editor run
--     update public.app_settings set admin_mfa_required = false where id = 1;
-- Admin access then works with the normal login only (the app skips the code screen too).
-- To start over with a new phone: Authentication -> Users -> your user -> remove the MFA factor, then enrol again.
-- Turn it back on afterwards:
--     update public.app_settings set admin_mfa_required = true where id = 1;
--
-- Safe to run more than once.

alter table public.app_settings add column if not exists admin_mfa_required boolean not null default true;

create or replace function public.admin_mfa_required()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select s.admin_mfa_required from public.app_settings s where s.id = 1), true);
$$;
revoke all on function public.admin_mfa_required() from public, anon;
grant execute on function public.admin_mfa_required() to authenticated, service_role;

-- The check used by every admin_* function.
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins a where a.user_id = auth.uid())
    and (not public.admin_mfa_required() or coalesce(auth.jwt()->>'aal', '') = 'aal2');
$$;
revoke all on function public.is_admin() from public, anon;
grant execute on function public.is_admin() to authenticated;

-- For the app only (shows the admin link / the 2-step screens). It grants nothing: data still needs is_admin().
create or replace function public.admin_status()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'admin', exists (select 1 from public.admins a where a.user_id = auth.uid()),
    'mfa_required', public.admin_mfa_required(),
    'aal', coalesce(auth.jwt()->>'aal', 'aal1'));
$$;
revoke all on function public.admin_status() from public, anon;
grant execute on function public.admin_status() to authenticated;

-- ======================================================================
-- migrations/2026-11-23-v37-announcement-popup.sql
-- ======================================================================
-- v37: in the Android app the owner announcement opens as a popup when the app opens.
-- app_settings.announcement_secs = how many seconds the popup stays before it closes by itself (3..120, default 8).
-- Idempotent.
alter table public.app_settings add column if not exists announcement_secs int not null default 8;
alter table public.app_settings drop constraint if exists app_settings_announcement_secs_check;
alter table public.app_settings add constraint app_settings_announcement_secs_check check (announcement_secs between 3 and 120);

create or replace function public.get_app_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'announcement', s.announcement, 'announcement_hi', s.announcement_hi, 'announcement_secs', s.announcement_secs,
    'maintenance', s.maintenance, 'maintenance_msg', s.maintenance_msg,
    'min_app_version', s.min_app_version, 'free_counter_limit', s.free_counter_limit,
    'login_design', s.login_design, 'login_designs', s.login_designs,
    'landing_design', s.landing_design, 'landing_designs', s.landing_designs)
  from public.app_settings s where s.id = 1;
$$;
grant execute on function public.get_app_settings() to anon, authenticated;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  v_ok text[] := array['classic', 'modern', 'split', 'bento', 'bentofull'];
  v_land jsonb := '{}'::jsonb;
  v_land_ok text[] := array['classic', 'duo', 'bold'];
  k text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) = any(v_ok) then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  if jsonb_typeof(p->'landing_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'landing_designs'->>k) = any(v_land_ok) then
        v_land := v_land || jsonb_build_object(k, p->'landing_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    -- an older admin page sends no popup time: keep the current one
    announcement_secs = case when jsonb_typeof(p->'announcement_secs') = 'number' then least(greatest((p->>'announcement_secs')::numeric::int, 3), 120) else announcement_secs end,
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when (p->>'login_design') = any(v_ok) then p->>'login_design' else login_design end,
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    -- an older admin page sends no landing fields: keep the current ones
    landing_design   = case when (p->>'landing_design') = any(v_land_ok) then p->>'landing_design' else landing_design end,
    landing_designs  = case when jsonb_typeof(p->'landing_designs') = 'object' then v_land else landing_designs end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;

-- ======================================================================
-- migrations/2026-11-24-v38-client-errors.sql
-- ======================================================================
-- PrintQR v38 (2026-11-24): every production problem reaches the Admin bell.
--   1. report_client_error(): the website / Android app / Windows app report their own crashes and
--      failed server calls into public.ops_events (level 'client'). The 15-minute health check turns them
--      into the "Errors on website / app" alert. Capped so a broken page can't flood the table.
--   2. ops_alert_set(): GitHub workflows (deploy, migrations, functions, backup, app builds ...) open or
--      close their own alert when a run fails / passes (service role only, from .github/workflows/alerts.yml).
-- Safe to run more than once. Needs v25 (ops_events) and v30 (ops_alerts).

create index if not exists ops_events_source_idx on public.ops_events (source, created_at);

create or replace function public.report_client_error(p_source text, p_message text, p_where text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_src text := case when p_source in ('web', 'app', 'desktop') then 'client-' || p_source else 'client-web' end;
  v_msg text;
begin
  v_msg := left(regexp_replace(regexp_replace(
             coalesce(nullif(trim(p_message), ''), 'unknown error') || coalesce(' @ ' || left(nullif(trim(p_where), ''), 80), ''),
             '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<email>', 'g'),
             'eyJ[A-Za-z0-9._-]{20,}', '<token>', 'g'), 300);
  -- at most 300 client reports per 10 minutes in total, and the same message once per 5 minutes
  if (select count(*) from public.ops_events where source like 'client-%' and created_at > now() - interval '10 minutes') >= 300 then return; end if;
  if exists (select 1 from public.ops_events where source = v_src and message = v_msg and created_at > now() - interval '5 minutes') then return; end if;
  insert into public.ops_events (source, level, message) values (v_src, 'client', v_msg);
end $$;
revoke all on function public.report_client_error(text, text, text) from public;
grant execute on function public.report_client_error(text, text, text) to anon, authenticated;

create or replace function public.ops_alert_set(p_key text, p_title text, p_detail text, p_bad boolean)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v_id bigint;
begin
  select id into v_id from public.ops_alerts where key = p_key and closed_at is null;
  if p_bad then
    if v_id is null then
      insert into public.ops_alerts (key, title, detail) values (left(p_key, 60), left(p_title, 120), left(coalesce(p_detail, ''), 500));
      return 'opened';
    end if;
    update public.ops_alerts set last_seen = now(), detail = left(coalesce(p_detail, ''), 500) where id = v_id;
    return 'still';
  elsif v_id is not null then
    update public.ops_alerts set closed_at = now() where id = v_id;
    return 'closed';
  end if;
  return 'ok';
end $$;
revoke all on function public.ops_alert_set(text, text, text, boolean) from public, anon, authenticated;
grant execute on function public.ops_alert_set(text, text, text, boolean) to service_role;

-- ======================================================================
-- migrations/2026-11-24-v39-admin-tools.sql
-- ======================================================================
-- PrintQR v39 (2026-11-24): Admin panel tools.
--   1. Admin roles: public.admins.role 'owner' | 'support' (existing admins = owner). is_owner_admin() helper;
--      money / settings / shop-changing admin functions are owner-only from now on.
--   2. Error viewer: client error reports keep route, app version, device (user agent) and stack (ops_events).
--   3. Growth graphs: admin_growth() daily series (new shops, orders, pages, payments) for the last 30 days.
--   4. Support inbox: shops send problems / feedback (support_tickets); admins reply and mark solved; the reply
--      reaches the shop as an in-app notice (shop_notices).
--   5. Coupon codes: free Pro days (coupons, coupon_redemptions); one redemption per shop per code.
--   6. Expiring plans + inactive shops lists; reminders / nudges (push + in-app notice) are sent by admin-action.
--   7. Targeted push: push_segment_owners() for the admin-action Edge Function (service role only).
--   8. View as shop: admin_shop_view() read-only summary.
--   9. CSV export: admin_export().
--  10. Admin login alert: admin_device_seen() records each admin device; a new device opens an alert in the bell
--      and asks the health-check function to push it at once.
--  11. Backup status: backup_report() (service role, from .github/workflows/backup.yml), admin_backup_status().
-- Safe to run more than once. Needs v30 (ops_alerts), v36 (admin 2-step login), v38 (client errors).

-- ============ 1. Admin roles ============
alter table public.admins add column if not exists role text not null default 'owner';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'admins_role_check') then
    alter table public.admins add constraint admins_role_check check (role in ('owner', 'support'));
  end if;
end $$;

-- Full admin (owner): payments, settings, coupons, push, plan / block changes.
create or replace function public.is_owner_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() and exists (select 1 from public.admins a where a.user_id = auth.uid() and a.role = 'owner');
$$;
revoke all on function public.is_owner_admin() from public, anon;
grant execute on function public.is_owner_admin() to authenticated, service_role;

-- admin_status() also says the role (the page hides tabs with it; every function checks again).
create or replace function public.admin_status()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'admin', exists (select 1 from public.admins a where a.user_id = auth.uid()),
    'role', (select a.role from public.admins a where a.user_id = auth.uid()),
    'mfa_required', public.admin_mfa_required(),
    'aal', coalesce(auth.jwt()->>'aal', 'aal1'));
$$;
revoke all on function public.admin_status() from public, anon;
grant execute on function public.admin_status() to authenticated;

-- Owner: every admin with email and role.
create or replace function public.admin_list()
returns table (user_id uuid, email text, role text, created_at timestamptz, is_me boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return query
  select a.user_id, coalesce(u.email, u.phone)::text, a.role, a.created_at, a.user_id = auth.uid()
  from public.admins a left join auth.users u on u.id = a.user_id
  order by a.created_at;
end $$;
revoke all on function public.admin_list() from public, anon;
grant execute on function public.admin_list() to authenticated;

-- Owner: change an admin's role. The last owner cannot be made support (nobody could change it back).
create or replace function public.admin_set_role(p_user uuid, p_role text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_old text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if p_role not in ('owner', 'support') then raise exception 'bad role'; end if;
  select role into v_old from public.admins where user_id = p_user for update;
  if not found then raise exception 'not an admin'; end if;
  if v_old = p_role then return; end if;
  if v_old = 'owner' and (select count(*) from public.admins where role = 'owner') <= 1 then
    raise exception 'last owner';
  end if;
  update public.admins set role = p_role where user_id = p_user;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'role_changed', null, jsonb_build_object('user_id', p_user, 'role', p_role, 'before', v_old));
end $$;
revoke all on function public.admin_set_role(uuid, text) from public, anon;
grant execute on function public.admin_set_role(uuid, text) to authenticated;

-- The functions below are the latest versions (v13 .. v37) with only the first check changed to is_owner_admin():
-- support admins can read shops / users / orders / spam, but not change plans, blocks, settings or see payments.
create or replace function public.admin_set_pro(p_shop uuid, p_days int, p_tier text default null)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_end timestamptz;
  v_tier text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if p_days is null or p_days < 0 or p_days > 3660 then raise exception 'bad days'; end if;
  if p_tier is not null and p_tier not in ('pro', 'plus') then raise exception 'bad plan'; end if;
  select * into v_shop from public.shops where id = p_shop for update;
  if not found then raise exception 'Shop not found'; end if;
  if p_days = 0 then
    update public.shops set plan = 'free', plan_expires_at = now() where id = p_shop;
    v_end := now();
  else
    -- No plan named: keep the shop's current paid plan (Plus stays Plus), otherwise Pro.
    v_tier := coalesce(p_tier, case when public.is_pro(v_shop) and v_shop.plan in ('pro', 'plus') then v_shop.plan else 'pro' end);
    v_end := greatest(coalesce(v_shop.plan_expires_at, now()), now()) + make_interval(days => p_days);
    update public.shops set plan = v_tier, plan_expires_at = v_end where id = p_shop;
  end if;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), case when p_days = 0 then 'pro_removed' else 'pro_given' end, p_shop,
            jsonb_build_object('days', p_days, 'until', v_end, 'before', v_shop.plan_expires_at,
                               'plan', coalesce(v_tier, 'free'), 'plan_before', v_shop.plan));
  return v_end;
end $$;

create or replace function public.admin_set_blocked(p_shop uuid, p_blocked boolean, p_reason text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  update public.shops set blocked = coalesce(p_blocked, false),
    blocked_reason = case when p_blocked then left(nullif(trim(p_reason), ''), 200) else null end
  where id = p_shop;
  if not found then raise exception 'Shop not found'; end if;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), case when p_blocked then 'blocked' else 'unblocked' end, p_shop, jsonb_build_object('reason', p_reason));
end $$;


create or replace function public.admin_reset_qr(p_shop uuid)
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  delete from public.qr_links where shop_id = p_shop;
  get diagnostics n = row_count;
  insert into public.admin_log (admin_id, action, shop_id, detail) values (auth.uid(), 'qr_reset', p_shop, jsonb_build_object('codes', n));
  return n;
end $$;


create or replace function public.admin_edit_shop(p_shop uuid, p_name text default null, p_remove_logo boolean default false)
returns void language plpgsql security definer set search_path = public as $$
declare v_old text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  select name into v_old from public.shops where id = p_shop;
  if not found then raise exception 'Shop not found'; end if;
  update public.shops set
    name = coalesce(nullif(trim(p_name), ''), name),
    logo_url = case when p_remove_logo then null else logo_url end
  where id = p_shop;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'shop_edited', p_shop, jsonb_build_object('old_name', v_old, 'new_name', nullif(trim(p_name), ''), 'logo_removed', p_remove_logo));
end $$;


create or replace function public.admin_payments()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'subs', coalesce((select jsonb_agg(x order by x.plan_expires_at desc nulls last) from (
      select s.id as shop_id, s.name, coalesce(nullif(u.email, '')::text, '+' || nullif(u.phone, '')::text) as email,
        s.plan, s.plan_period, s.subscription_status,
        s.plan_expires_at, s.razorpay_subscription_id as sub_id, public.is_pro(s) as is_pro
      from public.shops s left join auth.users u on u.id = s.owner_id
      where s.razorpay_subscription_id is not null) x), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(e order by e.received_at desc) from (
      select event, received_at from public.billing_events order by received_at desc limit 30) e), '[]'::jsonb)
  );
end $$;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  v_ok text[] := array['classic', 'modern', 'split', 'bento', 'bentofull'];
  v_land jsonb := '{}'::jsonb;
  v_land_ok text[] := array['classic', 'duo', 'bold'];
  k text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) = any(v_ok) then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  if jsonb_typeof(p->'landing_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'landing_designs'->>k) = any(v_land_ok) then
        v_land := v_land || jsonb_build_object(k, p->'landing_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    -- an older admin page sends no popup time: keep the current one
    announcement_secs = case when jsonb_typeof(p->'announcement_secs') = 'number' then least(greatest((p->>'announcement_secs')::numeric::int, 3), 120) else announcement_secs end,
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when (p->>'login_design') = any(v_ok) then p->>'login_design' else login_design end,
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    -- an older admin page sends no landing fields: keep the current ones
    landing_design   = case when (p->>'landing_design') = any(v_land_ok) then p->>'landing_design' else landing_design end,
    landing_designs  = case when jsonb_typeof(p->'landing_designs') = 'object' then v_land else landing_designs end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;


create or replace function public.admin_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  r jsonb;
  v_cron timestamptz;
  v_cron_fail int;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  select jsonb_build_object(
    'shops_total',   (select count(*) from public.shops),
    'shops_today',   (select count(*) from public.shops where created_at >= date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata'),
    'shops_week',    (select count(*) from public.shops where created_at >= now() - interval '7 days'),
    'pro_active',    (select count(*) from public.shops s where public.is_pro(s)),
    'pro_paid',      (select count(*) from public.shops s where public.is_pro(s) and s.razorpay_subscription_id is not null),
    'pro_monthly',   (select count(*) from public.shops s where public.is_pro(s) and s.plan = 'pro' and s.razorpay_subscription_id is not null and s.plan_period = 'monthly'),
    'pro_yearly',    (select count(*) from public.shops s where public.is_pro(s) and s.plan = 'pro' and s.razorpay_subscription_id is not null and s.plan_period = 'yearly'),
    'plus_active',   (select count(*) from public.shops s where public.is_plus(s)),
    'plus_monthly',  (select count(*) from public.shops s where public.is_plus(s) and s.razorpay_subscription_id is not null and s.plan_period = 'monthly'),
    'plus_yearly',   (select count(*) from public.shops s where public.is_plus(s) and s.razorpay_subscription_id is not null and s.plan_period = 'yearly'),
    'pay_failed',    (select count(*) from public.shops where subscription_status in ('halted', 'pending')),
    'blocked',       (select count(*) from public.shops where blocked),
    'orders_today',  (select count(*) from public.orders where status <> 'uploading' and created_at >= date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata'),
    'orders_week',   (select count(*) from public.orders where status <> 'uploading' and created_at >= now() - interval '7 days'),
    'orders_total',  (select count(*) from public.orders where status <> 'uploading'),
    'orders_stuck',  (select count(*) from public.orders where not files_deleted and
                        ((status = 'uploading' and created_at < now() - interval '1 hour')
                         or (status in ('received', 'printing') and created_at < now() - interval '1 day'))),
    'storage_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'uploads'),
    'files_waiting', (select count(*) from public.orders where not files_deleted and status <> 'uploading'),
    'reports_open',  (select count(*) from public.shop_reports where not resolved),
    'users_total',   (select count(*) from auth.users)
  ) into r;
  begin
    select max(d.end_time) filter (where d.status = 'succeeded'),
           count(*) filter (where d.status = 'failed' and d.start_time > now() - interval '1 day')
      into v_cron, v_cron_fail
    from cron.job_run_details d where d.start_time > now() - interval '7 days';
    r := r || jsonb_build_object('cleanup_last', v_cron, 'cleanup_failed_day', v_cron_fail);
  exception when others then
    r := r || jsonb_build_object('cleanup_last', null, 'cleanup_failed_day', null);
  end;
  return r;
end $$;


-- ============ 2. Error viewer ============
alter table public.ops_events add column if not exists route text;
alter table public.ops_events add column if not exists app_version text;
alter table public.ops_events add column if not exists ua text;
alter table public.ops_events add column if not exists stack text;
create index if not exists ops_events_level_idx on public.ops_events (level, created_at);

-- Old 3-argument version is replaced (named-argument calls from older apps still match the new one).
drop function if exists public.report_client_error(text, text, text);
create or replace function public.report_client_error(p_source text, p_message text, p_where text default null,
  p_route text default null, p_version text default null, p_ua text default null, p_stack text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_src text := case when p_source in ('web', 'app', 'desktop') then 'client-' || p_source else 'client-web' end;
  v_msg text;
  v_stack text;
begin
  v_msg := left(regexp_replace(regexp_replace(
             coalesce(nullif(trim(p_message), ''), 'unknown error') || coalesce(' @ ' || left(nullif(trim(p_where), ''), 80), ''),
             '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<email>', 'g'),
             'eyJ[A-Za-z0-9._-]{20,}', '<token>', 'g'), 300);
  v_stack := left(regexp_replace(regexp_replace(nullif(trim(p_stack), ''),
             '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<email>', 'g'),
             'eyJ[A-Za-z0-9._-]{20,}', '<token>', 'g'), 2000);
  -- at most 300 client reports per 10 minutes in total, and the same message once per 5 minutes
  if (select count(*) from public.ops_events where source like 'client-%' and created_at > now() - interval '10 minutes') >= 300 then return; end if;
  if exists (select 1 from public.ops_events where source = v_src and message = v_msg and created_at > now() - interval '5 minutes') then return; end if;
  insert into public.ops_events (source, level, message, route, app_version, ua, stack)
  values (v_src, 'client', v_msg,
          left(regexp_replace(nullif(trim(p_route), ''), '[?#].*$', ''), 120),
          left(nullif(trim(p_version), ''), 40), left(nullif(trim(p_ua), ''), 300), v_stack);
end $$;
revoke all on function public.report_client_error(text, text, text, text, text, text, text) from public;
grant execute on function public.report_client_error(text, text, text, text, text, text, text) to anon, authenticated;

-- Client errors of the last p_hours (max 30 days), grouped by message: count, first / last seen, newest 20 reports.
create or replace function public.admin_client_errors(p_hours int default 24)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_since timestamptz := now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), 720));
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('message', g.message, 'count', g.n, 'first_seen', g.first_seen, 'last_seen', g.last_seen,
      'sources', g.sources,
      'items', (select coalesce(jsonb_agg(jsonb_build_object('at', x.created_at, 'source', x.source, 'route', x.route,
                  'version', x.app_version, 'ua', x.ua, 'stack', x.stack) order by x.created_at desc), '[]'::jsonb)
                from (select * from public.ops_events e2 where e2.level = 'client' and e2.message = g.message and e2.created_at >= v_since
                      order by e2.created_at desc limit 20) x))
      order by g.last_seen desc)
    from (select e.message, count(*)::int as n, min(e.created_at) as first_seen, max(e.created_at) as last_seen,
                 jsonb_agg(distinct e.source) as sources
          from public.ops_events e where e.level = 'client' and e.created_at >= v_since
          group by e.message order by max(e.created_at) desc limit 200) g), '[]'::jsonb);
end $$;
revoke all on function public.admin_client_errors(int) from public, anon;
grant execute on function public.admin_client_errors(int) to authenticated;

-- ============ 3. Growth graphs ============
-- One row per India day: new shops, orders (finished uploads), pages printed (pages x copies),
-- payments (count, rupees) and upgrades (shops paying for the first time).
create or replace function public.admin_growth(p_days int default 30)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_days int := least(greatest(coalesce(p_days, 30), 7), 90);
  v_to date := (now() at time zone 'Asia/Kolkata')::date;
  v_from date := v_to - (v_days - 1);
  v_start timestamptz := (v_from::timestamp at time zone 'Asia/Kolkata');
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('day', d.day, 'shops', coalesce(s.n, 0), 'orders', coalesce(o.n, 0),
      'pages', coalesce(o.pages, 0), 'payments', coalesce(p.n, 0), 'amount', coalesce(p.rupees, 0), 'upgrades', coalesce(u.n, 0))
      order by d.day)
    from (select generate_series(v_from, v_to, interval '1 day')::date as day) d
    left join (select (created_at at time zone 'Asia/Kolkata')::date as day, count(*)::int as n
               from public.shops where created_at >= v_start group by 1) s on s.day = d.day
    left join (select (o.created_at at time zone 'Asia/Kolkata')::date as day, count(*)::int as n,
                      coalesce(sum((select sum(f.pages_to_print * f.copies) from public.order_files f where f.order_id = o.id)), 0)::bigint as pages
               from public.orders o where o.created_at >= v_start and o.status not in ('uploading', 'cancelled') group by 1) o on o.day = d.day
    left join (select (paid_at at time zone 'Asia/Kolkata')::date as day, count(*)::int as n, (sum(amount) / 100)::bigint as rupees
               from public.billing_payments where paid_at >= v_start group by 1) p on p.day = d.day
    left join (select (first_paid at time zone 'Asia/Kolkata')::date as day, count(*)::int as n
               from (select shop_id, min(paid_at) as first_paid from public.billing_payments group by shop_id) f
               where first_paid >= v_start group by 1) u on u.day = d.day), '[]'::jsonb);
end $$;
revoke all on function public.admin_growth(int) from public, anon;
grant execute on function public.admin_growth(int) to authenticated;

-- ============ 4. In-app notices for shops + support inbox ============
create table if not exists public.shop_notices (
  id bigint generated always as identity primary key,
  shop_id uuid not null references public.shops(id) on delete cascade,
  kind text not null check (kind in ('support', 'expiring', 'nudge', 'admin')),
  title text,
  body text,
  data jsonb not null default '{}'::jsonb,
  created_by uuid,
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists shop_notices_shop_idx on public.shop_notices (shop_id, created_at desc);
alter table public.shop_notices enable row level security;  -- no policies: owners read through my_notices()
revoke all on public.shop_notices from public, anon, authenticated;
grant select, insert, update on public.shop_notices to service_role;

create table if not exists public.support_tickets (
  id bigint generated always as identity primary key,
  shop_id uuid not null references public.shops(id) on delete cascade,
  user_id uuid references auth.users(id) on delete set null,
  topic text not null default 'problem' check (topic in ('problem', 'feedback', 'billing', 'other')),
  message text not null check (char_length(message) between 3 and 2000),
  app text,
  status text not null default 'open' check (status in ('open', 'solved')),
  reply text,
  replied_at timestamptz,
  replied_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists support_tickets_status_idx on public.support_tickets (status, created_at desc);
create index if not exists support_tickets_shop_idx on public.support_tickets (shop_id, created_at desc);
alter table public.support_tickets enable row level security;  -- no policies: only through the functions below
revoke all on public.support_tickets from public, anon, authenticated;

-- The caller's own shop (owner only; staff and admins viewing do not count).
create or replace function public.my_shop_id()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.shops where owner_id = auth.uid() limit 1;
$$;
revoke all on function public.my_shop_id() from public, anon;
grant execute on function public.my_shop_id() to authenticated;

-- Shop owner: unread notices + the last 30 days (max 20).
create or replace function public.my_notices()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid := public.my_shop_id();
begin
  if v_shop is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'kind', n.kind, 'title', n.title, 'body', n.body, 'data', n.data,
      'created_at', n.created_at, 'read_at', n.read_at) order by n.created_at desc)
    from (select * from public.shop_notices where shop_id = v_shop and (read_at is null or created_at > now() - interval '30 days')
          order by created_at desc limit 20) n), '[]'::jsonb);
end $$;
revoke all on function public.my_notices() from public, anon;
grant execute on function public.my_notices() to authenticated;

-- Shop owner: mark one notice (or all, p_id null) as read.
create or replace function public.notice_read(p_id bigint default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := public.my_shop_id();
begin
  if v_shop is null then return; end if;
  update public.shop_notices set read_at = now() where shop_id = v_shop and read_at is null and (p_id is null or id = p_id);
end $$;
revoke all on function public.notice_read(bigint) from public, anon;
grant execute on function public.notice_read(bigint) to authenticated;

-- Shop owner: send a problem / feedback to the PrintQR team (max 5 a day per shop).
create or replace function public.support_submit(p_topic text, p_message text, p_app text default null)
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := public.my_shop_id(); v_id bigint;
begin
  if v_shop is null then raise exception 'not allowed'; end if;
  if char_length(trim(coalesce(p_message, ''))) < 3 then raise exception 'message too short'; end if;
  if (select count(*) from public.support_tickets where shop_id = v_shop and created_at > now() - interval '1 day') >= 5 then
    raise exception 'too many requests';
  end if;
  insert into public.support_tickets (shop_id, user_id, topic, message, app)
  values (v_shop, auth.uid(), case when p_topic in ('problem', 'feedback', 'billing', 'other') then p_topic else 'other' end,
          left(trim(p_message), 2000), left(nullif(trim(p_app), ''), 120))
  returning id into v_id;
  return v_id;
end $$;
revoke all on function public.support_submit(text, text, text) from public, anon;
grant execute on function public.support_submit(text, text, text) to authenticated;

-- Shop owner: own requests with the team's reply (last 20).
create or replace function public.my_support()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid := public.my_shop_id();
begin
  if v_shop is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'topic', t.topic, 'message', t.message, 'status', t.status,
      'reply', t.reply, 'replied_at', t.replied_at, 'created_at', t.created_at) order by t.created_at desc)
    from (select * from public.support_tickets where shop_id = v_shop order by created_at desc limit 20) t), '[]'::jsonb);
end $$;
revoke all on function public.my_support() from public, anon;
grant execute on function public.my_support() to authenticated;

-- Admin (owner or support): the inbox. p_status 'open' | 'solved' | 'all'.
create or replace function public.admin_support(p_status text default 'open', p_limit int default 100)
returns table (id bigint, shop_id uuid, shop_name text, slug text, owner_email text, phone text, topic text, message text, app text,
  status text, reply text, replied_at timestamptz, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return query
  select t.id, t.shop_id, s.name, s.slug, coalesce(u.email, u.phone)::text, s.phone, t.topic, t.message, t.app,
    t.status, t.reply, t.replied_at, t.created_at
  from public.support_tickets t join public.shops s on s.id = t.shop_id left join auth.users u on u.id = s.owner_id
  where coalesce(p_status, 'open') = 'all' or t.status = p_status
  order by t.status = 'open' desc, t.created_at desc
  limit least(greatest(coalesce(p_limit, 100), 1), 300);
end $$;
revoke all on function public.admin_support(text, int) from public, anon;
grant execute on function public.admin_support(text, int) to authenticated;

-- Admin (owner or support): reply (shown to the shop as a notice) and / or mark open / solved.
create or replace function public.admin_support_reply(p_id bigint, p_reply text default null, p_status text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_t public.support_tickets; v_reply text := left(nullif(trim(p_reply), ''), 2000);
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_status is not null and p_status not in ('open', 'solved') then raise exception 'bad status'; end if;
  select * into v_t from public.support_tickets where id = p_id for update;
  if not found then raise exception 'not found'; end if;
  update public.support_tickets set
    reply = coalesce(v_reply, reply),
    replied_at = case when v_reply is not null then now() else replied_at end,
    replied_by = case when v_reply is not null then auth.uid() else replied_by end,
    status = coalesce(p_status, status),
    updated_at = now()
  where id = p_id;
  if v_reply is not null then
    insert into public.shop_notices (shop_id, kind, title, body, data, created_by)
    values (v_t.shop_id, 'support', null, v_reply, jsonb_build_object('ticket', p_id, 'question', left(v_t.message, 200)), auth.uid());
  end if;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'support_reply', v_t.shop_id, jsonb_build_object('ticket', p_id, 'replied', v_reply is not null, 'status', coalesce(p_status, v_t.status)));
end $$;
revoke all on function public.admin_support_reply(bigint, text, text) from public, anon;
grant execute on function public.admin_support_reply(bigint, text, text) to authenticated;

-- ============ 5. Coupon codes (free Pro / Plus days) ============
create table if not exists public.coupons (
  code text primary key check (code ~ '^[A-Z0-9_-]{3,30}$'),
  kind text not null default 'days' check (kind in ('days')),
  days int not null check (days between 1 and 366),
  tier text not null default 'pro' check (tier in ('pro', 'plus')),
  expires_at timestamptz,
  max_uses int check (max_uses is null or max_uses >= 1),
  uses int not null default 0,
  active boolean not null default true,
  note text,
  created_by uuid,
  created_at timestamptz not null default now()
);
alter table public.coupons enable row level security;
revoke all on public.coupons from public, anon, authenticated;

create table if not exists public.coupon_redemptions (
  code text not null references public.coupons(code) on delete cascade,
  shop_id uuid not null references public.shops(id) on delete cascade,
  user_id uuid,
  days int not null,
  until timestamptz not null,
  created_at timestamptz not null default now(),
  primary key (code, shop_id)
);
alter table public.coupon_redemptions enable row level security;
revoke all on public.coupon_redemptions from public, anon, authenticated;

-- Wrong codes per shop (brute-force guard: 10 wrong tries an hour).
create table if not exists public.coupon_tries (
  id bigint generated always as identity primary key,
  shop_id uuid not null,
  created_at timestamptz not null default now()
);
create index if not exists coupon_tries_shop_idx on public.coupon_tries (shop_id, created_at);
alter table public.coupon_tries enable row level security;
revoke all on public.coupon_tries from public, anon, authenticated;

create or replace function public.admin_coupons()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'kind', c.kind, 'days', c.days, 'tier', c.tier,
      'expires_at', c.expires_at, 'max_uses', c.max_uses, 'uses', c.uses, 'active', c.active, 'note', c.note, 'created_at', c.created_at)
      order by c.created_at desc) from public.coupons c), '[]'::jsonb);
end $$;
revoke all on function public.admin_coupons() from public, anon;
grant execute on function public.admin_coupons() to authenticated;

-- Owner: create or change a code (code is saved in capitals).
create or replace function public.admin_coupon_save(p_code text, p_days int, p_tier text default 'pro', p_expires_at timestamptz default null,
  p_max_uses int default null, p_active boolean default true, p_note text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_code text := upper(trim(coalesce(p_code, '')));
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if v_code !~ '^[A-Z0-9_-]{3,30}$' then raise exception 'bad code'; end if;
  if p_days is null or p_days < 1 or p_days > 366 then raise exception 'bad days'; end if;
  if coalesce(p_tier, 'pro') not in ('pro', 'plus') then raise exception 'bad plan'; end if;
  insert into public.coupons (code, days, tier, expires_at, max_uses, active, note, created_by)
  values (v_code, p_days, coalesce(p_tier, 'pro'), p_expires_at, nullif(p_max_uses, 0), coalesce(p_active, true), left(nullif(trim(p_note), ''), 200), auth.uid())
  on conflict (code) do update set days = excluded.days, tier = excluded.tier, expires_at = excluded.expires_at,
    max_uses = excluded.max_uses, active = excluded.active, note = excluded.note;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'coupon_saved', null, jsonb_build_object('code', v_code, 'days', p_days, 'tier', coalesce(p_tier, 'pro'),
            'active', coalesce(p_active, true), 'max_uses', p_max_uses, 'expires_at', p_expires_at));
end $$;
revoke all on function public.admin_coupon_save(text, int, text, timestamptz, int, boolean, text) from public, anon;
grant execute on function public.admin_coupon_save(text, int, text, timestamptz, int, boolean, text) to authenticated;

-- Shop owner: redeem a code. Adds the free days on top of the current plan end (Plus stays Plus).
-- Returns {ok, until, days, plan} or {ok:false, error:'not_found'|'expired'|'used_up'|'already'|'too_many'}.
create or replace function public.redeem_coupon(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_tier text;
  v_end timestamptz;
  v_err text;
begin
  select * into v_shop from public.shops where owner_id = auth.uid() for update;
  if not found then raise exception 'not allowed'; end if;
  if v_shop.blocked then raise exception 'not allowed'; end if;
  if (select count(*) from public.coupon_tries where shop_id = v_shop.id and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code for update;
  if not found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = v_shop.id) then v_err := 'already';
  end if;
  if v_err is not null then
    insert into public.coupon_tries (shop_id) values (v_shop.id);
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  v_tier := case when public.is_plus(v_shop) or v_c.tier = 'plus' then 'plus' else 'pro' end;
  v_end := greatest(coalesce(v_shop.plan_expires_at, now()), now()) + make_interval(days => v_c.days);
  update public.shops set plan = v_tier, plan_expires_at = v_end where id = v_shop.id;
  update public.coupons set uses = uses + 1 where code = v_code;
  insert into public.coupon_redemptions (code, shop_id, user_id, days, until) values (v_code, v_shop.id, auth.uid(), v_c.days, v_end);
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (null, 'coupon_redeemed', v_shop.id, jsonb_build_object('code', v_code, 'days', v_c.days, 'until', v_end,
            'before', v_shop.plan_expires_at, 'plan', v_tier, 'plan_before', v_shop.plan));
  return jsonb_build_object('ok', true, 'until', v_end, 'days', v_c.days, 'plan', v_tier);
end $$;
revoke all on function public.redeem_coupon(text) from public, anon;
grant execute on function public.redeem_coupon(text) to authenticated;

-- ============ 6. Expiring plans, inactive shops ============
create or replace function public.admin_expiring(p_days int default 7)
returns table (id uuid, name text, slug text, owner_email text, phone text, plan text, plan_expires_at timestamptz,
  paid boolean, subscription_status text, last_reminded timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return query
  select s.id, s.name, s.slug, coalesce(u.email, u.phone)::text, s.phone, s.plan, s.plan_expires_at,
    s.razorpay_subscription_id is not null, s.subscription_status,
    (select max(n.created_at) from public.shop_notices n where n.shop_id = s.id and n.kind = 'expiring')
  from public.shops s left join auth.users u on u.id = s.owner_id
  where s.plan in ('pro', 'plus') and not s.blocked
    and s.plan_expires_at > now() and s.plan_expires_at <= now() + make_interval(days => least(greatest(coalesce(p_days, 7), 1), 60))
  order by s.plan_expires_at;
end $$;
revoke all on function public.admin_expiring(int) from public, anon;
grant execute on function public.admin_expiring(int) to authenticated;

-- Shops with no finished order for p_days days that joined at least p_days days ago (they had time to start).
create or replace function public.admin_inactive(p_days int default 14, p_limit int default 100)
returns table (id uuid, name text, slug text, owner_email text, phone text, created_at timestamptz, is_pro boolean,
  orders_total int, last_order_at timestamptz, last_nudged timestamptz)
language plpgsql stable security definer set search_path = public as $$
declare v_since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 14), 1), 365));
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return query
  select x.id, x.name, x.slug, x.email, x.phone, x.created_at, x.pro, x.total, x.last_at,
    (select max(n.created_at) from public.shop_notices n where n.shop_id = x.id and n.kind = 'nudge')
  from (
    select s.id, s.name, s.slug, coalesce(u.email, u.phone)::text as email, s.phone, s.created_at, public.is_pro(s) as pro,
      (select count(*)::int from public.orders o where o.shop_id = s.id and o.status <> 'uploading') as total,
      (select max(o.created_at) from public.orders o where o.shop_id = s.id and o.status <> 'uploading') as last_at
    from public.shops s left join auth.users u on u.id = s.owner_id
    where not s.blocked and s.created_at < v_since
  ) x
  where x.last_at is null or x.last_at < v_since
  order by x.last_at desc nulls last, x.created_at desc
  limit least(greatest(coalesce(p_limit, 100), 1), 500);
end $$;
revoke all on function public.admin_inactive(int, int) from public, anon;
grant execute on function public.admin_inactive(int, int) to authenticated;

-- ============ 7. Targeted push ============
-- Segment: 'all' | 'pro' (Pro or Plus now) | 'free' | 'city' (address contains p_city). Blocked shops never.
create or replace function public.push_segment_owners(p_segment text, p_city text default null)
returns table (shop_id uuid, owner_id uuid)
language sql stable security definer set search_path = public as $$
  select s.id, s.owner_id from public.shops s
  where not s.blocked and case coalesce(p_segment, '')
    when 'all' then true
    when 'pro' then public.is_pro(s)
    when 'free' then not public.is_pro(s)
    when 'city' then char_length(trim(coalesce(p_city, ''))) >= 2 and coalesce(s.address, '') ilike '%' || trim(p_city) || '%'
    else false end;
$$;
revoke all on function public.push_segment_owners(text, text) from public, anon, authenticated;
grant execute on function public.push_segment_owners(text, text) to service_role;

-- Owner: how many shops / devices a segment reaches (preview before sending).
create or replace function public.admin_segment_count(p_segment text, p_city text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return (select jsonb_build_object('shops', count(distinct g.shop_id),
      'devices', (select count(*) from public.push_tokens t where t.owner_id in (select g2.owner_id from public.push_segment_owners(p_segment, p_city) g2)))
    from public.push_segment_owners(p_segment, p_city) g);
end $$;
revoke all on function public.admin_segment_count(text, text) from public, anon;
grant execute on function public.admin_segment_count(text, text) to authenticated;

-- ============ 8. View as shop (read-only) ============
-- No customer names or file names (same privacy rule as the Orders tab). Payments only for owner admins.
create or replace function public.admin_shop_view(p_shop uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_s public.shops; v_out jsonb;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select * into v_s from public.shops where id = p_shop;
  if not found then raise exception 'Shop not found'; end if;
  v_out := jsonb_build_object(
    'shop', jsonb_build_object('id', v_s.id, 'name', v_s.name, 'slug', v_s.slug, 'address', v_s.address, 'phone', v_s.phone,
      'upi', v_s.upi_id is not null, 'is_open', v_s.is_open, 'rates', v_s.rates, 'auto_delete_hours', v_s.auto_delete_hours,
      'hours', v_s.hours, 'paper_sheets', v_s.paper_sheets, 'brand_color', v_s.brand_color, 'logo', v_s.logo_url is not null,
      'plan', v_s.plan, 'is_pro', public.is_pro(v_s), 'plan_period', v_s.plan_period, 'plan_expires_at', v_s.plan_expires_at,
      'subscription_status', v_s.subscription_status, 'blocked', v_s.blocked, 'blocked_reason', v_s.blocked_reason, 'created_at', v_s.created_at),
    'owner_email', (select coalesce(u.email, u.phone) from auth.users u where u.id = v_s.owner_id),
    'counters', coalesce((select jsonb_agg(c.name order by c.created_at) from public.counters c where c.shop_id = p_shop), '[]'::jsonb),
    'staff', (select count(*) from public.shop_staff st where st.shop_id = p_shop),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('token', o.token, 'status', o.status, 'total', o.total,
        'counter', o.counter_name, 'created_at', o.created_at, 'files_deleted', o.files_deleted,
        'files', (select count(*) from public.order_files f where f.order_id = o.id),
        'pages', (select coalesce(sum(f.pages_to_print * f.copies), 0) from public.order_files f where f.order_id = o.id)) order by o.created_at desc)
      from (select * from public.orders where shop_id = p_shop and status <> 'uploading' order by created_at desc limit 50) o), '[]'::jsonb),
    'tickets', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'status', t.status, 'message', left(t.message, 200), 'created_at', t.created_at) order by t.created_at desc)
      from (select * from public.support_tickets where shop_id = p_shop order by created_at desc limit 10) t), '[]'::jsonb),
    'payments', case when public.is_owner_admin() then coalesce((select jsonb_agg(jsonb_build_object('amount', bp.amount, 'tier', bp.tier,
        'period', bp.period, 'paid_at', bp.paid_at) order by bp.paid_at desc)
      from (select * from public.billing_payments where shop_id = p_shop order by paid_at desc limit 20) bp), '[]'::jsonb) else null end);
  insert into public.admin_log (admin_id, action, shop_id, detail) values (auth.uid(), 'shop_viewed', p_shop, '{}'::jsonb);
  return v_out;
end $$;
revoke all on function public.admin_shop_view(uuid) from public, anon;
grant execute on function public.admin_shop_view(uuid) to authenticated;

-- ============ 9. CSV export ============
-- Owner: rows for 'shops' | 'orders' | 'payments' created between p_from and p_to (India dates, both optional). Max 20000 rows.
create or replace function public.admin_export(p_kind text, p_from date default null, p_to date default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_a timestamptz := coalesce((p_from::timestamp at time zone 'Asia/Kolkata'), '-infinity'::timestamptz);
  v_b timestamptz := coalesce(((p_to + 1)::timestamp at time zone 'Asia/Kolkata'), 'infinity'::timestamptz);
  v_out jsonb;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if p_kind = 'shops' then
    select coalesce(jsonb_agg(r order by r->>'created_at'), '[]'::jsonb) into v_out from (
      select jsonb_build_object('id', s.id, 'name', s.name, 'slug', s.slug, 'owner', coalesce(u.email, u.phone), 'phone', s.phone,
        'address', s.address, 'plan', s.plan, 'is_pro', public.is_pro(s), 'plan_period', s.plan_period, 'plan_expires_at', s.plan_expires_at,
        'subscription_status', s.subscription_status, 'blocked', s.blocked, 'created_at', s.created_at,
        'orders', (select count(*) from public.orders o where o.shop_id = s.id and o.status <> 'uploading')) as r
      from public.shops s left join auth.users u on u.id = s.owner_id
      where s.created_at >= v_a and s.created_at < v_b order by s.created_at limit 20000) x;
  elsif p_kind = 'orders' then
    select coalesce(jsonb_agg(r order by r->>'created_at'), '[]'::jsonb) into v_out from (
      select jsonb_build_object('id', o.id, 'shop', s.name, 'shop_slug', s.slug, 'token', o.token, 'status', o.status, 'total', o.total,
        'counter', o.counter_name, 'files', (select count(*) from public.order_files f where f.order_id = o.id),
        'pages', (select coalesce(sum(f.pages_to_print * f.copies), 0) from public.order_files f where f.order_id = o.id),
        'paid_at', o.paid_at, 'created_at', o.created_at) as r
      from public.orders o join public.shops s on s.id = o.shop_id
      where o.status <> 'uploading' and o.created_at >= v_a and o.created_at < v_b order by o.created_at limit 20000) x;
  elsif p_kind = 'payments' then
    select coalesce(jsonb_agg(r order by r->>'paid_at'), '[]'::jsonb) into v_out from (
      select jsonb_build_object('payment_id', p.payment_id, 'shop', s.name, 'shop_slug', s.slug, 'tier', p.tier, 'period', p.period,
        'amount_rupees', round(p.amount / 100.0, 2), 'currency', p.currency, 'subscription_id', p.subscription_id,
        'period_start', p.period_start, 'period_end', p.period_end, 'paid_at', p.paid_at) as r
      from public.billing_payments p join public.shops s on s.id = p.shop_id
      where p.paid_at >= v_a and p.paid_at < v_b order by p.paid_at limit 20000) x;
  else
    raise exception 'bad kind';
  end if;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'export', null, jsonb_build_object('kind', p_kind, 'from', p_from, 'to', p_to, 'rows', jsonb_array_length(v_out)));
  return v_out;
end $$;
revoke all on function public.admin_export(text, date, date) from public, anon;
grant execute on function public.admin_export(text, date, date) to authenticated;

-- ============ 10. Admin login from a new device ============
create table if not exists public.admin_devices (
  user_id uuid not null references auth.users(id) on delete cascade,
  device_id text not null check (char_length(device_id) between 8 and 64),
  ua text,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  primary key (user_id, device_id)
);
alter table public.admin_devices enable row level security;  -- no policies
revoke all on public.admin_devices from public, anon, authenticated;

-- Called by the Admin page right after sign-in, also before the 2-step code (a password-only sign-in on a new
-- device is exactly what should be reported). The first device an admin ever records is saved quietly.
-- A new device opens an ops alert (bell) and asks the health-check function to push it to every admin now.
create or replace function public.admin_device_seen(p_device text, p_ua text default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_first boolean; v_email text; v_key text; v_tok text;
begin
  if v_uid is null or not exists (select 1 from public.admins where user_id = v_uid) then raise exception 'not allowed'; end if;
  if p_device is null or p_device !~ '^[A-Za-z0-9_-]{8,64}$' then raise exception 'bad device'; end if;
  update public.admin_devices set last_seen = now(), ua = coalesce(left(nullif(trim(p_ua), ''), 300), ua)
    where user_id = v_uid and device_id = p_device;
  if found then return false; end if;
  if (select count(*) from public.admin_devices where user_id = v_uid and first_seen > now() - interval '1 day') >= 20 then return false; end if;
  v_first := not exists (select 1 from public.admin_devices where user_id = v_uid);
  insert into public.admin_devices (user_id, device_id, ua) values (v_uid, p_device, left(nullif(trim(p_ua), ''), 300))
    on conflict do nothing;
  if v_first then return false; end if;
  select coalesce(email, phone) into v_email from auth.users where id = v_uid;
  v_key := 'admin_login_' || left(md5(v_uid::text || p_device), 12);
  insert into public.ops_alerts (key, title, detail)
  values (v_key, 'Admin login from new device',
          left(coalesce(v_email, v_uid::text) || ' signed in on a new device ('
               || to_char(now() at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST): ' || coalesce(left(p_ua, 200), 'unknown device')
               || '. Not you? Change the password and remove the device in Supabase Auth.', 500))
  on conflict do nothing;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (v_uid, 'admin_new_device', null, jsonb_build_object('ua', left(p_ua, 200)));
  -- push at once (health-check in push-only mode); without pg_net / token the 15-minute run sends it
  begin
    select token into v_tok from private.cron_tokens where name = 'health';
    if v_tok is not null then
      perform net.http_post(
        url := 'https://asqgdgzxkdksoikmffmd.supabase.co/functions/v1/health-check',
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-token', v_tok),
        body := '{"mode":"push"}'::jsonb,
        timeout_milliseconds := 30000);
    end if;
  exception when others then null;
  end;
  return true;
end $$;
revoke all on function public.admin_device_seen(text, text) from public, anon;
grant execute on function public.admin_device_seen(text, text) to authenticated;

-- ============ 11. Backup status ============
create table if not exists public.backup_runs (
  id bigint generated always as identity primary key,
  ran_at timestamptz not null default now(),
  status text not null check (status in ('ok', 'failed', 'skipped')),
  size_bytes bigint,
  detail text
);
create index if not exists backup_runs_ran_idx on public.backup_runs (ran_at desc);
alter table public.backup_runs enable row level security;  -- no policies
revoke all on public.backup_runs from public, anon, authenticated;
grant select on public.backup_runs to service_role;

-- GitHub backup workflow (service role, same key as alerts.yml) records each run.
create or replace function public.backup_report(p_status text, p_size bigint default null, p_detail text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if p_status not in ('ok', 'failed', 'skipped') then raise exception 'bad status'; end if;
  insert into public.backup_runs (status, size_bytes, detail)
  values (p_status, case when p_size >= 0 then p_size end, left(nullif(trim(p_detail), ''), 300));
  delete from public.backup_runs where ran_at < now() - interval '180 days';
end $$;
revoke all on function public.backup_report(text, bigint, text) from public, anon, authenticated;
grant execute on function public.backup_report(text, bigint, text) to service_role;

create or replace function public.admin_backup_status()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'last', (select jsonb_build_object('ran_at', ran_at, 'status', status, 'size_bytes', size_bytes, 'detail', detail)
             from public.backup_runs order by ran_at desc limit 1),
    'last_ok', (select jsonb_build_object('ran_at', ran_at, 'size_bytes', size_bytes)
                from public.backup_runs where status = 'ok' order by ran_at desc limit 1));
end $$;
revoke all on function public.admin_backup_status() from public, anon;
grant execute on function public.admin_backup_status() to authenticated;

-- service role (Edge Functions): shop owners' push tokens and notices
grant select on public.push_tokens to service_role;
grant select on public.shops to service_role;

-- ======================================================================
-- migrations/2026-11-24-v40-percent-coupons.sql
-- ======================================================================
-- PrintQR v40 (2026-11-24): percent-off coupon codes, applied by Razorpay.
--   1. coupons.kind 'percent' next to 'days': percent (1-90), tiers (pro / plus), periods (monthly / yearly), mode:
--        'auto'  - every billing cycle is discounted: the create-subscription Edge Function makes (once) a discounted
--                  Razorpay plan per tier + period + percent and caches it in billing_plans_discount (never in
--                  billing_plans, so normal checkout can never get a discounted plan).
--        'offer' - the subscription is made on the normal plan with a Razorpay offer_id (offer made in the Razorpay
--                  Dashboard and linked to the PrintQR plans, e.g. first 3 months off).
--   2. coupon_checkouts: one row per subscription made with a code (service role). The code counts as used only
--      after payment: coupon_paid() (verify-payment / webhook) writes coupon_redemptions once, idempotently.
--   3. coupon_check(): service-role validation (active, not expired, uses left incl. checkouts in progress,
--      one per shop, 10 wrong tries an hour like redeem_coupon).
--   4. redeem_coupon() (free days) answers 'checkout' for a % code instead of redeeming it.
--   5. Admin (owner only): admin_coupons() shows the new fields, admin_coupon_save_percent() creates / edits % codes.
-- Safe to run more than once. Needs v39 (coupons, is_owner_admin).

-- ============ 1. coupons: percent kind ============
alter table public.coupons add column if not exists percent int;
alter table public.coupons add column if not exists tiers text[];
alter table public.coupons add column if not exists periods text[];
alter table public.coupons add column if not exists mode text;
alter table public.coupons add column if not exists offer_id text;
alter table public.coupons alter column days drop not null;
alter table public.coupons drop constraint if exists coupons_kind_check;
alter table public.coupons drop constraint if exists coupons_days_check;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'coupons_kind_v40_check') then
    alter table public.coupons add constraint coupons_kind_v40_check check (kind in ('days', 'percent'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'coupons_shape_v40_check') then
    alter table public.coupons add constraint coupons_shape_v40_check check (
      (kind = 'days' and days between 1 and 366)
      or (kind = 'percent'
        and mode in ('auto', 'offer')
        and (percent between 1 and 90 or (mode = 'offer' and percent is null))
        and coalesce(array_length(tiers, 1), 0) >= 1 and tiers <@ array['pro', 'plus']::text[]
        and coalesce(array_length(periods, 1), 0) >= 1 and periods <@ array['monthly', 'yearly']::text[]
        and (mode = 'auto' or offer_id ~ '^offer_[A-Za-z0-9]{6,40}$')));
  end if;
end $$;

-- Redemptions of % codes have no days / end date; they point at the paid subscription instead.
alter table public.coupon_redemptions alter column days drop not null;
alter table public.coupon_redemptions alter column until drop not null;
alter table public.coupon_redemptions add column if not exists kind text not null default 'days';
alter table public.coupon_redemptions add column if not exists percent int;
alter table public.coupon_redemptions add column if not exists subscription_id text;

-- ============ 2. Discounted Razorpay plans (separate from billing_plans) ============
create table if not exists public.billing_plans_discount (
  tier text not null check (tier in ('pro', 'plus')),
  period text not null check (period in ('monthly', 'yearly')),
  percent int not null check (percent between 1 and 90),
  base_amount int not null,
  amount int not null check (amount >= 100),
  razorpay_plan_id text not null unique,
  created_at timestamptz not null default now(),
  primary key (tier, period, percent, base_amount)
);
alter table public.billing_plans_discount enable row level security;
revoke all on public.billing_plans_discount from public, anon, authenticated;
grant all on public.billing_plans_discount to service_role;

-- Subscriptions made with a code (written by create-subscription, service role).
create table if not exists public.coupon_checkouts (
  subscription_id text primary key,
  code text not null references public.coupons(code) on delete cascade,
  shop_id uuid not null references public.shops(id) on delete cascade,
  tier text not null check (tier in ('pro', 'plus')),
  period text not null check (period in ('monthly', 'yearly')),
  mode text not null check (mode in ('auto', 'offer')),
  percent int,
  amount int,
  offer_id text,
  created_at timestamptz not null default now(),
  paid_at timestamptz
);
create index if not exists coupon_checkouts_code_idx on public.coupon_checkouts (code, created_at);
alter table public.coupon_checkouts enable row level security;
revoke all on public.coupon_checkouts from public, anon, authenticated;
grant all on public.coupon_checkouts to service_role;

-- ============ 3. Validation (service role, from create-subscription) ============
-- Returns {ok:true, kind, code, percent, mode, offer_id, tiers, periods, days, tier}
--      or {ok:false, error:'not_found'|'expired'|'used_up'|'already'|'too_many'|'blocked'}.
-- Uses left counts checkouts started by other shops in the last 30 minutes and not paid yet.
create or replace function public.coupon_check(p_shop uuid, p_code text, p_log boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_pending int;
  v_err text;
  v_blocked boolean;
  v_found boolean;
begin
  select s.blocked into v_blocked from public.shops s where s.id = p_shop;
  if not found or coalesce(v_blocked, false) then return jsonb_build_object('ok', false, 'error', 'blocked'); end if;
  if (select count(*) from public.coupon_tries where shop_id = p_shop and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code;
  v_found := found;
  if v_found then
    select count(distinct k.shop_id) into v_pending from public.coupon_checkouts k
      where k.code = v_code and k.paid_at is null and k.shop_id <> p_shop and k.created_at > now() - interval '30 minutes';
  end if;
  if not v_found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses + coalesce(v_pending, 0) >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = p_shop) then v_err := 'already';
  end if;
  if v_err is not null then
    if coalesce(p_log, true) then insert into public.coupon_tries (shop_id) values (p_shop); end if;
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  return jsonb_build_object('ok', true, 'kind', v_c.kind, 'code', v_c.code, 'percent', v_c.percent, 'mode', v_c.mode,
    'offer_id', v_c.offer_id, 'tiers', to_jsonb(v_c.tiers), 'periods', to_jsonb(v_c.periods), 'days', v_c.days, 'tier', v_c.tier,
    'expires_at', v_c.expires_at);
end $$;
revoke all on function public.coupon_check(uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.coupon_check(uuid, text, boolean) to service_role;

-- Payment went through for a subscription made with a code: record the redemption once (repeats do nothing).
create or replace function public.coupon_paid(p_sub text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_k public.coupon_checkouts;
  v_n int;
begin
  select * into v_k from public.coupon_checkouts where subscription_id = p_sub for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'no_checkout'); end if;
  if v_k.paid_at is not null then return jsonb_build_object('ok', true, 'repeat', true); end if;
  update public.coupon_checkouts set paid_at = now() where subscription_id = p_sub;
  insert into public.coupon_redemptions (code, shop_id, user_id, days, until, kind, percent, subscription_id)
    values (v_k.code, v_k.shop_id, null, null, null, 'percent', v_k.percent, p_sub)
    on conflict (code, shop_id) do nothing;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    update public.coupons set uses = uses + 1 where code = v_k.code;
    insert into public.admin_log (admin_id, action, shop_id, detail)
      values (null, 'coupon_redeemed', v_k.shop_id, jsonb_build_object('code', v_k.code, 'percent', v_k.percent, 'mode', v_k.mode,
              'tier', v_k.tier, 'period', v_k.period, 'amount', v_k.amount, 'subscription_id', p_sub));
  end if;
  return jsonb_build_object('ok', true, 'counted', v_n > 0);
end $$;
revoke all on function public.coupon_paid(text) from public, anon, authenticated;
grant execute on function public.coupon_paid(text) to service_role;

-- ============ 4. Free-days redeem: a % code is used at checkout instead ============
create or replace function public.redeem_coupon(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_tier text;
  v_end timestamptz;
  v_err text;
begin
  select * into v_shop from public.shops where owner_id = auth.uid() for update;
  if not found then raise exception 'not allowed'; end if;
  if v_shop.blocked then raise exception 'not allowed'; end if;
  if (select count(*) from public.coupon_tries where shop_id = v_shop.id and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code for update;
  -- % code: nothing is redeemed here; the Plan tab checks it through create-subscription and applies it at payment.
  if found and v_c.active and v_c.kind = 'percent' then
    return jsonb_build_object('ok', false, 'error', 'checkout', 'code', v_code);
  end if;
  if not found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = v_shop.id) then v_err := 'already';
  end if;
  if v_err is not null then
    insert into public.coupon_tries (shop_id) values (v_shop.id);
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  v_tier := case when public.is_plus(v_shop) or v_c.tier = 'plus' then 'plus' else 'pro' end;
  v_end := greatest(coalesce(v_shop.plan_expires_at, now()), now()) + make_interval(days => v_c.days);
  update public.shops set plan = v_tier, plan_expires_at = v_end where id = v_shop.id;
  update public.coupons set uses = uses + 1 where code = v_code;
  insert into public.coupon_redemptions (code, shop_id, user_id, days, until) values (v_code, v_shop.id, auth.uid(), v_c.days, v_end);
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (null, 'coupon_redeemed', v_shop.id, jsonb_build_object('code', v_code, 'days', v_c.days, 'until', v_end,
            'before', v_shop.plan_expires_at, 'plan', v_tier, 'plan_before', v_shop.plan));
  return jsonb_build_object('ok', true, 'until', v_end, 'days', v_c.days, 'plan', v_tier);
end $$;
revoke all on function public.redeem_coupon(text) from public, anon;
grant execute on function public.redeem_coupon(text) to authenticated;

-- ============ 5. Admin (owner only) ============
create or replace function public.admin_coupons()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'kind', c.kind, 'days', c.days, 'tier', c.tier,
      'percent', c.percent, 'mode', c.mode, 'offer_id', c.offer_id, 'tiers', to_jsonb(c.tiers), 'periods', to_jsonb(c.periods),
      'expires_at', c.expires_at, 'max_uses', c.max_uses, 'uses', c.uses, 'active', c.active, 'note', c.note, 'created_at', c.created_at,
      'pending', (select count(*) from public.coupon_checkouts k where k.code = c.code and k.paid_at is null
                    and k.created_at > now() - interval '30 minutes'))
      order by c.created_at desc) from public.coupons c), '[]'::jsonb);
end $$;
revoke all on function public.admin_coupons() from public, anon;
grant execute on function public.admin_coupons() to authenticated;

-- Free-days codes: same as v39, but will not turn an existing % code into a days code.
create or replace function public.admin_coupon_save(p_code text, p_days int, p_tier text default 'pro', p_expires_at timestamptz default null,
  p_max_uses int default null, p_active boolean default true, p_note text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_code text := upper(trim(coalesce(p_code, '')));
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if v_code !~ '^[A-Z0-9_-]{3,30}$' then raise exception 'bad code'; end if;
  if p_days is null or p_days < 1 or p_days > 366 then raise exception 'bad days'; end if;
  if coalesce(p_tier, 'pro') not in ('pro', 'plus') then raise exception 'bad plan'; end if;
  if exists (select 1 from public.coupons where code = v_code and kind <> 'days') then raise exception 'code already used for a percent-off code'; end if;
  insert into public.coupons (code, kind, days, tier, expires_at, max_uses, active, note, created_by)
  values (v_code, 'days', p_days, coalesce(p_tier, 'pro'), p_expires_at, nullif(p_max_uses, 0), coalesce(p_active, true), left(nullif(trim(p_note), ''), 200), auth.uid())
  on conflict (code) do update set days = excluded.days, tier = excluded.tier, expires_at = excluded.expires_at,
    max_uses = excluded.max_uses, active = excluded.active, note = excluded.note;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'coupon_saved', null, jsonb_build_object('code', v_code, 'days', p_days, 'tier', coalesce(p_tier, 'pro'),
            'active', coalesce(p_active, true), 'max_uses', p_max_uses, 'expires_at', p_expires_at));
end $$;
revoke all on function public.admin_coupon_save(text, int, text, timestamptz, int, boolean, text) from public, anon;
grant execute on function public.admin_coupon_save(text, int, text, timestamptz, int, boolean, text) to authenticated;

-- % codes: create or change (code is saved in capitals). A days code cannot be turned into a % code.
create or replace function public.admin_coupon_save_percent(p_code text, p_percent int, p_tiers text[], p_periods text[],
  p_mode text default 'auto', p_offer_id text default null, p_expires_at timestamptz default null,
  p_max_uses int default null, p_active boolean default true, p_note text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_code text := upper(trim(coalesce(p_code, '')));
  v_mode text := coalesce(p_mode, 'auto');
  v_offer text := nullif(trim(coalesce(p_offer_id, '')), '');
  v_tiers text[] := (select array_agg(distinct x order by x) from unnest(coalesce(p_tiers, '{}'::text[])) x);
  v_periods text[] := (select array_agg(distinct x order by x) from unnest(coalesce(p_periods, '{}'::text[])) x);
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if v_code !~ '^[A-Z0-9_-]{3,30}$' then raise exception 'bad code'; end if;
  if v_mode not in ('auto', 'offer') then raise exception 'bad mode'; end if;
  if v_mode = 'auto' and (p_percent is null or p_percent < 1 or p_percent > 90) then raise exception 'percent must be 1 to 90'; end if;
  if v_mode = 'offer' and p_percent is not null and (p_percent < 1 or p_percent > 90) then raise exception 'percent must be 1 to 90'; end if;
  if v_tiers is null or not (v_tiers <@ array['pro', 'plus']::text[]) then raise exception 'bad plan'; end if;
  if v_periods is null or not (v_periods <@ array['monthly', 'yearly']::text[]) then raise exception 'bad period'; end if;
  if v_mode = 'offer' and (v_offer is null or v_offer !~ '^offer_[A-Za-z0-9]{6,40}$') then raise exception 'bad Razorpay offer id'; end if;
  if v_mode = 'auto' then v_offer := null; end if;
  if exists (select 1 from public.coupons where code = v_code and kind <> 'percent') then raise exception 'code already used for a free-days code'; end if;
  insert into public.coupons (code, kind, days, tier, percent, tiers, periods, mode, offer_id, expires_at, max_uses, active, note, created_by)
  values (v_code, 'percent', null, case when 'pro' = any(v_tiers) then 'pro' else 'plus' end, p_percent, v_tiers, v_periods, v_mode, v_offer, p_expires_at, nullif(p_max_uses, 0),
          coalesce(p_active, true), left(nullif(trim(p_note), ''), 200), auth.uid())
  on conflict (code) do update set percent = excluded.percent, tiers = excluded.tiers, periods = excluded.periods, tier = excluded.tier,
    mode = excluded.mode, offer_id = excluded.offer_id, expires_at = excluded.expires_at, max_uses = excluded.max_uses,
    active = excluded.active, note = excluded.note;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'coupon_saved', null, jsonb_build_object('code', v_code, 'percent', p_percent, 'mode', v_mode, 'tiers', to_jsonb(v_tiers),
            'periods', to_jsonb(v_periods), 'active', coalesce(p_active, true), 'max_uses', p_max_uses, 'expires_at', p_expires_at,
            'offer', v_offer is not null));
end $$;
revoke all on function public.admin_coupon_save_percent(text, int, text[], text[], text, text, timestamptz, int, boolean, text) from public, anon;
grant execute on function public.admin_coupon_save_percent(text, int, text[], text[], text, text, timestamptz, int, boolean, text) to authenticated;

-- ======================================================================
-- migrations/2026-11-24-v41-verified-pages.sql
-- ======================================================================
-- PrintQR v41 (2026-11-24): the shop's total comes from page counts the server checked, never from the customer's numbers.
--
-- Before: create_order priced each file from the pages the customer's app reported. finalize-order (v11) recounted
-- normal PDFs, but a PDF it could not read failed the order, photos / Office files / passport sheets kept the
-- customer's number, and nothing told the shop what was checked.
--
--   1. order_files gets a per-file check result:
--        pages_status  'verified'   the server counted the pages and the customer's number was right
--                      'corrected'  the server counted more (or fewer) pages and re-priced the file with the shop's rates
--                      'unverified' the pages could not be counted (Office file, encrypted / broken / very large PDF,
--                                   or finalize never ran). Every new row starts 'unverified'.
--        pages_note    why a file is unverified (office, encrypted, too_big, too_complex, unreadable, timeout, not_checked)
--        pages_real    pages the server counted (null when unverified)
--        claimed_pages / claimed_total_pages / claimed_price   what the customer's app said (kept for audit)
--      A trigger fills the claimed_* columns on insert, so create_order / reorder need no change.
--   2. finalize_order_verified() (service role, called by the finalize-order Edge Function): takes the server's
--      results per file, fixes pages / page range / price with file_price() and the shop's rates, sets pages_status,
--      recomputes the order total from the stored prices and queues the order.
--   3. finalize_order_counted() (v11 entry point, still used by an older deployed finalize-order) now goes through
--      finalize_order_verified(), so it records statuses too.
--   4. reorder_finalize() copies the check result of the original file (the bytes are the same).
-- Old orders keep pages_status null (no badge). Safe to run more than once. Needs v25 (finalize_begin) and v23.

-- ============ 1. per-file check result ============
alter table public.order_files add column if not exists pages_status text;
alter table public.order_files add column if not exists pages_note text;
alter table public.order_files add column if not exists pages_real int;
alter table public.order_files add column if not exists claimed_pages int;
alter table public.order_files add column if not exists claimed_total_pages int;
alter table public.order_files add column if not exists claimed_price numeric(10,2);
-- Default only for new rows: existing rows stay null (no badge on old orders).
alter table public.order_files alter column pages_status set default 'unverified';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'order_files_pages_status_v41_check') then
    alter table public.order_files add constraint order_files_pages_status_v41_check
      check (pages_status is null or pages_status in ('verified', 'corrected', 'unverified'));
  end if;
end $$;

-- The customer's numbers as sent, kept apart from the (possibly corrected) live values.
create or replace function public.order_files_claimed_v41()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.claimed_pages is null then new.claimed_pages := new.pages_to_print; end if;
  if new.claimed_total_pages is null then new.claimed_total_pages := new.total_pages; end if;
  if new.claimed_price is null then new.claimed_price := new.price; end if;
  if new.pages_status is null then new.pages_status := 'unverified'; end if;
  return new;
end $$;
revoke all on function public.order_files_claimed_v41() from public, anon, authenticated;
drop trigger if exists order_files_claimed_v41 on public.order_files;
create trigger order_files_claimed_v41 before insert on public.order_files
  for each row execute function public.order_files_claimed_v41();

-- ============ 2. page range helper ============
-- Pages in a range like '1-5, 8, 10-12' when every page is inside 1..p_total; null when the range is empty,
-- malformed or goes past the real page count.
create or replace function public.page_range_count(p_range text, p_total int)
returns int language plpgsql immutable set search_path = public as $$
declare
  v_part text;
  v_a int;
  v_b int;
  v_seen int[] := '{}';
  v_m text[];
begin
  if p_range is null or btrim(p_range) = '' or p_total is null or p_total < 1 then return null; end if;
  if length(p_range) > 60 then return null; end if;
  foreach v_part in array string_to_array(regexp_replace(p_range, '\s', '', 'g'), ',') loop
    if v_part = '' then continue; end if;
    v_m := regexp_match(v_part, '^([0-9]{1,4})(?:-([0-9]{1,4}))?$');
    if v_m is null then return null; end if;
    v_a := v_m[1]::int;
    v_b := coalesce(v_m[2]::int, v_a);
    if v_a < 1 or v_b < v_a or v_b > p_total then return null; end if;
    select array_agg(distinct x) into v_seen from unnest(v_seen || array(select generate_series(v_a, v_b))) x;
  end loop;
  if coalesce(array_length(v_seen, 1), 0) = 0 then return null; end if;
  return array_length(v_seen, 1);
end $$;
grant execute on function public.page_range_count(text, int) to service_role;

-- ============ 3. finalize with server-checked pages ============
-- p_result: { "<order_files.id>": { "pages": 50 } }  counted by the server
--           { "<order_files.id>": { "why": "encrypted" } }  could not be counted
-- Files missing from p_result are 'unverified' with note 'not_checked'. Photos are always 1 page.
create or replace function public.finalize_order_verified(p_order_id uuid, p_key uuid, p_result jsonb)
returns table (total numeric, changed int, unverified int)
language plpgsql security definer set search_path = public as $$
declare
  v_order public.orders;
  v_shop public.shops;
  v_f public.order_files;
  v_r jsonb;
  v_n int;
  v_why text;
  v_pages int;
  v_range text;
  v_range_n int;
  v_price numeric(10,2);
  v_status text;
  v_changed int := 0;
  v_unverified int := 0;
  v_missing int;
  v_total numeric(10,2);
begin
  select * into v_order from public.orders o
    where o.id = p_order_id and o.access_key = p_key and o.status = 'uploading' for update;
  if not found then raise exception 'Order not found'; end if;
  select * into v_shop from public.shops s where s.id = v_order.shop_id;
  if p_result is null or jsonb_typeof(p_result) <> 'object' then p_result := '{}'::jsonb; end if;

  for v_f in select * from public.order_files f where f.order_id = v_order.id order by f.storage_path loop
    v_r := p_result -> v_f.id::text;
    v_n := null;
    v_why := null;
    if jsonb_typeof(v_r) = 'object' and jsonb_typeof(v_r -> 'pages') = 'number' then
      v_n := (v_r ->> 'pages')::numeric::int;
      if v_n < 1 then v_n := null; v_why := 'unreadable'; end if;
    elsif jsonb_typeof(v_r) = 'object' then
      v_why := left(coalesce(v_r ->> 'why', 'unreadable'), 30);
    else
      v_why := 'not_checked';
    end if;
    if v_n is not null and v_n > 2000 then raise exception 'A PDF can have up to 2000 pages'; end if;

    -- Photos print as one page each, whatever the app said.
    if v_f.item_kind = 'print' and coalesce(v_f.mime, '') like 'image/%' then
      v_n := 1;
      v_why := null;
    elsif v_f.mime is distinct from 'application/pdf' then
      -- Word / Excel / PowerPoint: no converter on the server, the customer's number stays.
      v_n := null;
      v_why := 'office';
    end if;

    if v_n is null then
      v_unverified := v_unverified + 1;
      update public.order_files set pages_status = 'unverified', pages_note = coalesce(v_why, 'unreadable'), pages_real = null
        where id = v_f.id;
      continue;
    end if;

    if v_f.item_kind = 'passport' then
      -- Priced per sheet: a sheet PDF with more pages than its photos need is charged for every page.
      v_pages := greatest(v_f.pages_to_print, v_n);
      if v_pages <> v_f.pages_to_print then
        v_price := round(v_pages * coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40), 2);
        update public.order_files set pages_to_print = v_pages, total_pages = v_pages, price = v_price,
            pages_status = 'corrected', pages_note = null, pages_real = v_n
          where id = v_f.id;
        v_changed := v_changed + 1;
      else
        update public.order_files set pages_status = 'verified', pages_note = null, pages_real = v_n where id = v_f.id;
      end if;
      continue;
    end if;

    if v_f.item_kind = 'idcard' then
      -- finalize-order refuses an ID card sheet that is not exactly one page; priced per copy.
      if v_n <> 1 then raise exception 'The ID card sheet must be one page. Please make it again.'; end if;
      update public.order_files set pages_status = 'verified', pages_note = null, pages_real = 1 where id = v_f.id;
      continue;
    end if;

    -- Normal print file (PDF or photo). A page range is kept only when it fits inside the real pages;
    -- otherwise the whole file is what gets printed and charged.
    v_range := nullif(btrim(coalesce(v_f.page_range, '')), '');
    v_range_n := public.page_range_count(v_range, v_n);
    if v_range is not null and v_range_n is not null then
      v_pages := v_range_n;
    else
      v_range := null;
      v_pages := v_n;
    end if;
    v_price := public.file_price(v_shop.rates, v_pages, v_f.copies, v_f.color, v_f.duplex, v_f.binding, v_f.lamination);
    v_status := case when v_pages = v_f.pages_to_print and v_price = v_f.price
                       and v_range is not distinct from nullif(btrim(coalesce(v_f.page_range, '')), '')
                     then 'verified' else 'corrected' end;
    update public.order_files set pages_to_print = v_pages, total_pages = v_n, page_range = v_range, price = v_price,
        pages_status = v_status, pages_note = null, pages_real = v_n
      where id = v_f.id;
    if v_status = 'corrected' then v_changed := v_changed + 1; end if;
  end loop;

  select count(*) into v_missing from public.order_files f
    where f.order_id = v_order.id and not exists (
      select 1 from storage.objects so
      where so.bucket_id = 'uploads' and so.name = f.storage_path
        and (so.metadata->>'size')::bigint = f.size_bytes);
  if v_missing > 0 then raise exception 'Some files did not upload completely. Please try again.'; end if;

  -- The shop's total is always the sum of the stored (server-priced) file prices.
  select coalesce(sum(f.price), 0) into v_total from public.order_files f where f.order_id = v_order.id;
  update public.orders set total = v_total, status = 'received', updated_at = now() where id = v_order.id;
  return query select v_total::numeric, v_changed, v_unverified;
end $$;
revoke all on function public.finalize_order_verified(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.finalize_order_verified(uuid, uuid, jsonb) to service_role;

-- v11 entry point: { "<file id>": 50 } counts for print PDFs only. Same checks, same statuses.
create or replace function public.finalize_order_counted(p_order_id uuid, p_key uuid, p_counts jsonb)
returns table (total numeric, changed int)
language plpgsql security definer set search_path = public as $$
declare
  v_result jsonb := '{}'::jsonb;
  v_k text;
  v_v jsonb;
begin
  if p_counts is not null and jsonb_typeof(p_counts) = 'object' then
    for v_k, v_v in select * from jsonb_each(p_counts) loop
      if jsonb_typeof(v_v) = 'number' then v_result := v_result || jsonb_build_object(v_k, jsonb_build_object('pages', v_v)); end if;
    end loop;
  end if;
  return query select r.total, r.changed from public.finalize_order_verified(p_order_id, p_key, v_result) r;
end $$;
revoke all on function public.finalize_order_counted(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.finalize_order_counted(uuid, uuid, jsonb) to service_role;

-- ============ 4. reorder: same bytes, same check result ============
create or replace function public.reorder_finalize(p_order_id uuid, p_key uuid)
returns numeric language plpgsql security definer set search_path = public as $$
declare
  v_order public.orders;
  v_missing int;
begin
  select * into v_order from public.orders o
    where o.id = p_order_id and o.access_key = p_key and o.status = 'uploading' for update;
  if not found then raise exception 'Order not found'; end if;
  -- Only reorders (every file has a source); normal orders go through finalize_order_verified.
  if not exists (select 1 from public.order_files f where f.order_id = v_order.id)
     or exists (select 1 from public.order_files f where f.order_id = v_order.id and f.source_path is null) then
    raise exception 'Order not found';
  end if;
  select count(*) into v_missing from public.order_files f
    where f.order_id = v_order.id and not exists (
      select 1 from storage.objects so
      where so.bucket_id = 'uploads' and so.name = f.storage_path
        and coalesce((so.metadata->>'size')::bigint, f.size_bytes) = f.size_bytes);
  if v_missing > 0 then raise exception 'Some files could not be copied. Please try again.'; end if;
  -- Pages were checked (and if needed corrected) on the original order and reorder() priced from those, so a
  -- checked source is 'verified' here. Orders from before v41: PDFs were counted by v11, single photos are one page.
  update public.order_files nf set
      pages_status = case
        when sf.pages_status in ('verified', 'corrected') then 'verified'
        when sf.pages_status = 'unverified' then 'unverified'
        when sf.mime = 'application/pdf' or (coalesce(sf.mime, '') like 'image/%' and sf.pages_to_print = 1) then 'verified'
        else 'unverified' end,
      pages_note = case when sf.pages_status = 'unverified' then sf.pages_note
                        when sf.pages_status is null and sf.mime is distinct from 'application/pdf'
                             and not (coalesce(sf.mime, '') like 'image/%' and sf.pages_to_print = 1) then 'not_checked'
                        else null end,
      pages_real = sf.pages_real
    from public.order_files sf
    where nf.order_id = v_order.id and sf.storage_path = nf.source_path;
  update public.orders set status = 'received', updated_at = now() where id = v_order.id;
  return v_order.total;
end $$;
revoke all on function public.reorder_finalize(uuid, uuid) from public, anon, authenticated;
grant execute on function public.reorder_finalize(uuid, uuid) to service_role;

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-24-v42-coupon-switch.sql
-- ======================================================================
-- PrintQR v42 (2026-11-24): admin switch for coupon codes.
-- app_settings.coupons_enabled (default true). Off = the Plan tab hides "Have a coupon code?" and the server refuses
-- codes (redeem_coupon and coupon_check answer error 'disabled'). Codes already paid / redeemed are not touched.
-- Idempotent. Needs v39 (admin roles) and v40 (percent coupons).
alter table public.app_settings add column if not exists coupons_enabled boolean not null default true;

create or replace function public.get_app_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'announcement', s.announcement, 'announcement_hi', s.announcement_hi, 'announcement_secs', s.announcement_secs,
    'maintenance', s.maintenance, 'maintenance_msg', s.maintenance_msg,
    'min_app_version', s.min_app_version, 'free_counter_limit', s.free_counter_limit,
    'login_design', s.login_design, 'login_designs', s.login_designs,
    'landing_design', s.landing_design, 'landing_designs', s.landing_designs,
    'coupons_enabled', s.coupons_enabled)
  from public.app_settings s where s.id = 1;
$$;
grant execute on function public.get_app_settings() to anon, authenticated;

create or replace function public.admin_set_settings(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_designs jsonb := '{}'::jsonb;
  v_ok text[] := array['classic', 'modern', 'split', 'bento', 'bentofull'];
  v_land jsonb := '{}'::jsonb;
  v_land_ok text[] := array['classic', 'duo', 'bold'];
  k text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if coalesce(p->>'min_app_version', '') <> '' and (p->>'min_app_version') !~ '^\d+\.\d+\.\d+$' then
    raise exception 'bad version';
  end if;
  if jsonb_typeof(p->'login_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'login_designs'->>k) = any(v_ok) then
        v_designs := v_designs || jsonb_build_object(k, p->'login_designs'->>k);
      end if;
    end loop;
  end if;
  if jsonb_typeof(p->'landing_designs') = 'object' then
    foreach k in array array['app', 'mweb', 'web', 'desktop'] loop
      if (p->'landing_designs'->>k) = any(v_land_ok) then
        v_land := v_land || jsonb_build_object(k, p->'landing_designs'->>k);
      end if;
    end loop;
  end if;
  update public.app_settings set
    announcement     = left(nullif(trim(p->>'announcement'), ''), 300),
    announcement_hi  = left(nullif(trim(p->>'announcement_hi'), ''), 300),
    -- an older admin page sends no popup time: keep the current one
    announcement_secs = case when jsonb_typeof(p->'announcement_secs') = 'number' then least(greatest((p->>'announcement_secs')::numeric::int, 3), 120) else announcement_secs end,
    maintenance      = coalesce((p->>'maintenance')::boolean, false),
    maintenance_msg  = left(nullif(trim(p->>'maintenance_msg'), ''), 300),
    min_app_version  = nullif(trim(p->>'min_app_version'), ''),
    free_counter_limit = least(greatest(coalesce((p->>'free_counter_limit')::int, 0), 0), 20),
    login_design     = case when (p->>'login_design') = any(v_ok) then p->>'login_design' else login_design end,
    login_designs    = case when jsonb_typeof(p->'login_designs') = 'object' then v_designs else login_designs end,
    -- an older admin page sends no landing fields: keep the current ones
    landing_design   = case when (p->>'landing_design') = any(v_land_ok) then p->>'landing_design' else landing_design end,
    landing_designs  = case when jsonb_typeof(p->'landing_designs') = 'object' then v_land else landing_designs end,
    -- v42: an older admin page sends no coupon switch: keep the current one
    coupons_enabled  = case when jsonb_typeof(p->'coupons_enabled') = 'boolean' then (p->>'coupons_enabled')::boolean else coupons_enabled end,
    updated_at = now()
  where id = 1;
  insert into public.admin_log (admin_id, action, detail) values (auth.uid(), 'settings', p);
  return public.get_app_settings();
end $$;
revoke all on function public.admin_set_settings(jsonb) from public, anon;
grant execute on function public.admin_set_settings(jsonb) to authenticated;

create or replace function public.coupon_check(p_shop uuid, p_code text, p_log boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_pending int;
  v_err text;
  v_blocked boolean;
  v_found boolean;
begin
  select s.blocked into v_blocked from public.shops s where s.id = p_shop;
  if not found or coalesce(v_blocked, false) then return jsonb_build_object('ok', false, 'error', 'blocked'); end if;
  if not coalesce((select coupons_enabled from public.app_settings where id = 1), true) then
    return jsonb_build_object('ok', false, 'error', 'disabled');
  end if;
  if (select count(*) from public.coupon_tries where shop_id = p_shop and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code;
  v_found := found;
  if v_found then
    select count(distinct k.shop_id) into v_pending from public.coupon_checkouts k
      where k.code = v_code and k.paid_at is null and k.shop_id <> p_shop and k.created_at > now() - interval '30 minutes';
  end if;
  if not v_found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses + coalesce(v_pending, 0) >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = p_shop) then v_err := 'already';
  end if;
  if v_err is not null then
    if coalesce(p_log, true) then insert into public.coupon_tries (shop_id) values (p_shop); end if;
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  return jsonb_build_object('ok', true, 'kind', v_c.kind, 'code', v_c.code, 'percent', v_c.percent, 'mode', v_c.mode,
    'offer_id', v_c.offer_id, 'tiers', to_jsonb(v_c.tiers), 'periods', to_jsonb(v_c.periods), 'days', v_c.days, 'tier', v_c.tier,
    'expires_at', v_c.expires_at);
end $$;
revoke all on function public.coupon_check(uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.coupon_check(uuid, text, boolean) to service_role;

create or replace function public.redeem_coupon(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_tier text;
  v_end timestamptz;
  v_err text;
begin
  select * into v_shop from public.shops where owner_id = auth.uid() for update;
  if not found then raise exception 'not allowed'; end if;
  if v_shop.blocked then raise exception 'not allowed'; end if;
  if not coalesce((select coupons_enabled from public.app_settings where id = 1), true) then
    return jsonb_build_object('ok', false, 'error', 'disabled');
  end if;
  if (select count(*) from public.coupon_tries where shop_id = v_shop.id and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code for update;
  -- % code: nothing is redeemed here; the Plan tab checks it through create-subscription and applies it at payment.
  if found and v_c.active and v_c.kind = 'percent' then
    return jsonb_build_object('ok', false, 'error', 'checkout', 'code', v_code);
  end if;
  if not found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = v_shop.id) then v_err := 'already';
  end if;
  if v_err is not null then
    insert into public.coupon_tries (shop_id) values (v_shop.id);
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  v_tier := case when public.is_plus(v_shop) or v_c.tier = 'plus' then 'plus' else 'pro' end;
  v_end := greatest(coalesce(v_shop.plan_expires_at, now()), now()) + make_interval(days => v_c.days);
  update public.shops set plan = v_tier, plan_expires_at = v_end where id = v_shop.id;
  update public.coupons set uses = uses + 1 where code = v_code;
  insert into public.coupon_redemptions (code, shop_id, user_id, days, until) values (v_code, v_shop.id, auth.uid(), v_c.days, v_end);
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (null, 'coupon_redeemed', v_shop.id, jsonb_build_object('code', v_code, 'days', v_c.days, 'until', v_end,
            'before', v_shop.plan_expires_at, 'plan', v_tier, 'plan_before', v_shop.plan));
  return jsonb_build_object('ok', true, 'until', v_end, 'days', v_c.days, 'plan', v_tier);
end $$;
revoke all on function public.redeem_coupon(text) from public, anon;
grant execute on function public.redeem_coupon(text) to authenticated;

-- ======================================================================
-- migrations/2026-11-24-v43-support-alerts.sql
-- ======================================================================
-- PrintQR v43 (2026-11-24): new support message -> admin bell + push.
-- support_submit() opens an ops_alerts row 'support_<ticket id>' (the admin bell counts open alerts) and asks the
-- health-check function to push it to every admin device now; tapping the push opens Admin > Support.
-- admin_support_reply() closes that alert when the message gets a reply or is marked solved.
-- Idempotent. Needs v30 (ops_alerts), v39 (support tickets).

create or replace function public.support_submit(p_topic text, p_message text, p_app text default null)
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := public.my_shop_id(); v_id bigint; v_name text; v_tok text;
begin
  if v_shop is null then raise exception 'not allowed'; end if;
  if char_length(trim(coalesce(p_message, ''))) < 3 then raise exception 'message too short'; end if;
  if (select count(*) from public.support_tickets where shop_id = v_shop and created_at > now() - interval '1 day') >= 5 then
    raise exception 'too many requests';
  end if;
  insert into public.support_tickets (shop_id, user_id, topic, message, app)
  values (v_shop, auth.uid(), case when p_topic in ('problem', 'feedback', 'billing', 'other') then p_topic else 'other' end,
          left(trim(p_message), 2000), left(nullif(trim(p_app), ''), 120))
  returning id into v_id;
  -- v43: an open alert per message: the admin bell counts it, every admin phone / browser gets a push
  select name into v_name from public.shops where id = v_shop;
  insert into public.ops_alerts (key, title, detail)
  values ('support_' || v_id, 'New support message',
          left(coalesce(v_name, 'A shop') || ': ' || left(trim(p_message), 200), 300))
  on conflict do nothing;
  -- tell every admin device at once (health-check push-only mode); without pg_net / token the 15-minute run sends it
  begin
    select token into v_tok from private.cron_tokens where name = 'health';
    if v_tok is not null then
      perform net.http_post(
        url := 'https://asqgdgzxkdksoikmffmd.supabase.co/functions/v1/health-check',
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-token', v_tok),
        body := '{"mode":"push"}'::jsonb,
        timeout_milliseconds := 30000);
    end if;
  exception when others then null;
  end;
  return v_id;
end $$;
revoke all on function public.support_submit(text, text, text) from public, anon;
grant execute on function public.support_submit(text, text, text) to authenticated;

create or replace function public.admin_support_reply(p_id bigint, p_reply text default null, p_status text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_t public.support_tickets; v_reply text := left(nullif(trim(p_reply), ''), 2000);
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_status is not null and p_status not in ('open', 'solved') then raise exception 'bad status'; end if;
  select * into v_t from public.support_tickets where id = p_id for update;
  if not found then raise exception 'not found'; end if;
  update public.support_tickets set
    reply = coalesce(v_reply, reply),
    replied_at = case when v_reply is not null then now() else replied_at end,
    replied_by = case when v_reply is not null then auth.uid() else replied_by end,
    status = coalesce(p_status, status),
    updated_at = now()
  where id = p_id;
  -- v43: answered or solved -> the bell alert for this message closes
  if v_reply is not null or p_status = 'solved' then
    update public.ops_alerts set closed_at = now() where key = 'support_' || p_id and closed_at is null;
  end if;
  if v_reply is not null then
    insert into public.shop_notices (shop_id, kind, title, body, data, created_by)
    values (v_t.shop_id, 'support', null, v_reply, jsonb_build_object('ticket', p_id, 'question', left(v_t.message, 200)), auth.uid());
  end if;
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (auth.uid(), 'support_reply', v_t.shop_id, jsonb_build_object('ticket', p_id, 'replied', v_reply is not null, 'status', coalesce(p_status, v_t.status)));
end $$;
revoke all on function public.admin_support_reply(bigint, text, text) from public, anon;
grant execute on function public.admin_support_reply(bigint, text, text) to authenticated;

-- Messages already waiting (sent before v43) get their alert too, without a push.
insert into public.ops_alerts (key, title, detail, notified_at)
select 'support_' || t.id, 'New support message', left(coalesce(s.name, 'A shop') || ': ' || left(t.message, 200), 300), now()
from public.support_tickets t left join public.shops s on s.id = t.shop_id
where t.status = 'open' and t.reply is null
  and not exists (select 1 from public.ops_alerts a where a.key = 'support_' || t.id)
on conflict do nothing;

-- ======================================================================
-- migrations/2026-11-25-v44-security-fixes.sql
-- ======================================================================
-- PrintQR v44 migration (2026-11-25): security fixes. Safe to run more than once. Needs v25, v39, v42.
--
-- 1. Storage budgets (create_order): unfinished uploads ('uploading') count by the bytes really stored, not by
--    the sizes they declared, so orders that never upload hold no space. One network (request_ip_hash) may hold
--    at most app_settings.ip_pending_mb (default 250 MB) of declared-but-unfinished uploads in total, and at most
--    half of a shop's space (or one full order, if bigger) at one shop.
-- 2. reorder() ("Print again"): same Block sender, bot check (p_pass from upload-pass) and storage checks as
--    create_order; the network of a reprint is kept in order_senders too.
-- 3. redeem_coupon / coupon_check: a free-days Plus code on a running Pro plan is refused ('tier_higher_than_paid').
-- 4. report_client_error: at most 20 reports per 10 minutes per network, before the shared 300 cap.
-- 5. orders.files_deleted can be set by a shop owner / staff only when none of the order's files (or thumbnails)
--    is left in storage, so a half-done delete never hides files from auto-delete.

-- ============ settings + helpers ============
alter table public.app_settings add column if not exists ip_pending_mb int not null default 250;

create index if not exists order_senders_ip_idx on public.order_senders (ip_hash, created_at);

create or replace function public.ip_pending_cap_bytes()
returns bigint language sql stable security definer set search_path = public as $$
  select coalesce((select ip_pending_mb from public.app_settings where id = 1), 250)::bigint * 1048576;
$$;
revoke all on function public.ip_pending_cap_bytes() from public, anon, authenticated;

-- Bytes of files not yet deleted (whole service when p_shop is null): sent orders by their checked size
-- (finalize-order compares it with the stored file), unfinished uploads by what is really in storage.
create or replace function public.live_file_bytes(p_shop uuid)
returns bigint language sql stable security definer set search_path = public, storage as $$
  select coalesce((select sum(f.size_bytes) from public.order_files f join public.orders o on o.id = f.order_id
      where o.files_deleted = false and o.status <> 'uploading' and (p_shop is null or o.shop_id = p_shop)), 0)::bigint
    + coalesce((select sum(coalesce((so.metadata->>'size')::bigint, 0))
      from public.orders o
      join public.order_files f on f.order_id = o.id
      join storage.objects so on so.bucket_id = 'uploads' and so.name in (f.storage_path, f.storage_path || '.thumb.jpg')
      where o.files_deleted = false and o.status = 'uploading' and (p_shop is null or o.shop_id = p_shop)), 0)::bigint;
$$;
revoke all on function public.live_file_bytes(uuid) from public, anon, authenticated;

-- Declared bytes of one network's unfinished uploads (last 35 minutes; older ones are cleaned up).
create or replace function public.ip_pending_bytes(p_ip text, p_shop uuid)
returns bigint language sql stable security definer set search_path = public as $$
  select coalesce(sum(f.size_bytes), 0)::bigint
  from public.order_senders s
  join public.orders o on o.id = s.order_id
  join public.order_files f on f.order_id = o.id
  where s.ip_hash = p_ip and s.created_at > now() - interval '35 minutes'
    and o.status = 'uploading' and o.files_deleted = false
    and (p_shop is null or o.shop_id = p_shop);
$$;
revoke all on function public.ip_pending_bytes(text, uuid) from public, anon, authenticated;

-- ============ 1. create_order (from v25) ============
create or replace function public.create_order(p_slug text, p_customer_name text, p_note text, p_files jsonb, p_counter uuid default null,
  p_pass uuid default null)
returns table (order_id uuid, access_key uuid, token int, shop_id uuid, total numeric, paths text[])
language plpgsql security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_pro boolean;
  v_order public.orders;
  v_token int;
  v_total numeric(10,2) := 0;
  v_paths text[] := '{}';
  v_f jsonb;
  v_i int := 0;
  v_rate numeric;
  v_pages int;
  v_total_pages int;
  v_copies int;
  v_color boolean;
  v_duplex boolean;
  v_binding boolean;
  v_lam boolean;
  v_kind text;
  v_photos int;
  v_range text;
  v_price numeric(10,2);
  v_path text;
  v_counter_id uuid;
  v_counter_name text;
  v_ip text;
  v_ext text;
  v_mime text;
  v_size bigint;
  v_bytes bigint := 0;
  v_max bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Kolkata')) at time zone 'Asia/Kolkata';
  v_mode text;
  v_live_shop bigint;
  v_live_all bigint;
  v_cap_shop bigint;
  v_cap_all bigint;
begin
  select * into v_shop from public.shops where slug = p_slug for update;
  if not found then raise exception 'Shop not found'; end if;
  if not v_shop.is_open then raise exception 'Shop is closed right now'; end if;
  if p_files is null or jsonb_typeof(p_files) <> 'array' or jsonb_array_length(p_files) = 0 then
    raise exception 'No files';
  end if;
  if jsonb_array_length(p_files) > 20 then raise exception 'Max 20 files per order'; end if;

  -- Anti-spam (per 10 minutes, not per day: orders per day are unlimited on every plan).
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.order_rate where created_at < now() - interval '1 day';
    if (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many orders from this network. Please wait a few minutes and try again.';
    end if;
  end if;
  if (select count(*) from public.orders o where o.shop_id = v_shop.id and o.status = 'uploading'
        and o.created_at > now() - interval '30 minutes') >= 20
     or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'This shop is getting too many orders right now. Please try again in a few minutes.';
  end if;

  -- v25: the shop owner blocked this network ("Block sender" on an order).
  if v_ip is not null and exists (select 1 from public.shop_blocked_senders b where b.shop_id = v_shop.id and b.ip_hash = v_ip) then
    raise exception 'This shop is not accepting orders from your network.';
  end if;

  -- v25: bot check only when an order looks automated ('auto'), always ('always') or never ('off').
  -- 'captcha_required' makes the upload page show the Turnstile check, get a pass from upload-pass and retry.
  v_mode := coalesce((select order_captcha from public.app_settings where id = 1), 'auto');
  if v_mode = 'always' or (v_mode = 'auto' and (
       (v_ip is not null and (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 3)
       or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 20)) then
    if p_pass is null then raise exception 'captcha_required'; end if;
    delete from public.upload_pass up where up.created_at < now() - interval '1 hour';
    delete from public.upload_pass up where up.id = p_pass and up.created_at > now() - interval '10 minutes';
    if not found then raise exception 'captcha_required'; end if;
  end if;

  -- File checks: only print-able types, real sizes, each file up to 50 MB, the order up to the plan's size.
  v_max := public.plan_order_bytes(v_shop);
  for v_f in select * from jsonb_array_elements(p_files) loop
    v_ext := lower(substring(coalesce(v_f->>'name', '') from '\.([A-Za-z0-9]+)$'));
    v_mime := public.upload_mime_for(v_ext);
    if v_mime is null or coalesce(v_f->>'mime', '') <> v_mime then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    if v_f->>'kind' = 'idcard' and v_mime <> 'application/pdf' then
      raise exception 'File type not allowed: %. Send PDF, photo, Word, Excel or PowerPoint files.', left(coalesce(v_f->>'name', 'file'), 60);
    end if;
    v_size := coalesce((v_f->>'size')::bigint, 0);
    if v_size < 1 or v_size > 52428800 then raise exception 'Each file must be under 50 MB'; end if;
    v_bytes := v_bytes + v_size;
  end loop;
  if v_bytes > v_max then raise exception 'This shop accepts up to % MB per order', v_max / 1048576; end if;

  -- v25 + v44: storage budgets (files not yet auto-deleted), so a flood of uploads cannot fill the storage for everyone.
  -- v44: unfinished uploads count by the bytes really stored (public.live_file_bytes), not by the sizes they
  -- declared, so orders that never upload hold no space; and one network may hold only a limited amount of
  -- declared-but-unfinished uploads (public.ip_pending_bytes), in total and at this shop.
  v_cap_shop := public.shop_storage_bytes(v_shop);
  v_cap_all := public.storage_budget_bytes();
  if v_ip is not null then
    if public.ip_pending_bytes(v_ip, null) + v_bytes > public.ip_pending_cap_bytes()
       or public.ip_pending_bytes(v_ip, v_shop.id) + v_bytes > greatest(v_max, v_cap_shop / 2) then
      raise exception 'Too many unfinished uploads from your network right now. Please wait a few minutes and try again.';
    end if;
  end if;
  v_live_shop := public.live_file_bytes(v_shop.id);
  if v_live_shop + v_bytes > v_cap_shop then
    raise exception 'This shop''s file space is full right now. Please ask the shop to finish or clear old orders, then try again.';
  end if;
  v_live_all := public.live_file_bytes(null);
  if v_live_all + v_bytes > v_cap_all then
    raise exception 'Uploads are paused for a short while because the service is very busy. Please try again later.';
  end if;
  if v_ip is not null then insert into public.order_rate (ip_hash) values (v_ip); end if;
  v_pro := public.is_pro(v_shop);
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'passport') then
    raise exception 'Passport photo sheet is not available at this shop';
  end if;
  if not v_pro and exists (select 1 from jsonb_array_elements(p_files) x where x->>'kind' = 'idcard') then
    raise exception 'ID card sheet is not available at this shop';
  end if;

  if p_counter is not null then
    select c.id, c.name into v_counter_id, v_counter_name
      from public.counters c where c.id = p_counter and c.shop_id = v_shop.id
        and (v_pro or c.id in (
          select c2.id from public.counters c2 where c2.shop_id = v_shop.id
          order by c2.created_at, c2.id limit public.free_counter_limit()));
  end if;

  select coalesce(max(o.token), 0) + 1 into v_token
    from public.orders o where o.shop_id = v_shop.id and o.created_at >= v_day_start;

  insert into public.orders (shop_id, token, customer_name, note, counter_id, counter_name)
    values (v_shop.id, v_token, nullif(left(trim(coalesce(p_customer_name,'')), 60), ''),
      nullif(left(trim(coalesce(p_note,'')), 300), ''), v_counter_id, v_counter_name)
    returning * into v_order;
  if v_ip is not null then
    insert into public.order_senders (order_id, shop_id, ip_hash) values (v_order.id, v_shop.id, v_ip);
  end if;

  for v_f in select * from jsonb_array_elements(p_files) loop
    v_i := v_i + 1;
    v_kind := case when v_f->>'kind' in ('passport', 'idcard') then v_f->>'kind' else 'print' end;
    v_binding := false;
    v_lam := false;
    if v_kind = 'passport' then
      v_photos := greatest(1, least(300, coalesce((v_f->>'photos')::int, 8)));
      v_pages := ceil(v_photos / 30.0)::int;
      v_total_pages := v_pages;
      v_copies := 1;
      v_color := true;
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40);
      v_price := round(v_pages * v_copies * v_rate, 2);
    elsif v_kind = 'idcard' then
      -- One A4 page (front above back). finalize-order checks the PDF really has one page.
      v_photos := null;
      v_pages := 1;
      v_total_pages := 1;
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, true);
      v_duplex := false;
      v_range := null;
      v_rate := coalesce((v_shop.rates ->> 'idcard_sheet')::numeric, 20);
      v_price := round(v_copies * v_rate, 2);
    else
      v_photos := null;
      v_pages := greatest(1, least(2000, coalesce((v_f->>'pages_to_print')::int, 1)));
      v_total_pages := greatest(1, least(2000, coalesce((v_f->>'total_pages')::int, 1)));
      v_copies := greatest(1, least(100, coalesce((v_f->>'copies')::int, 1)));
      v_color := coalesce((v_f->>'color')::boolean, false);
      v_duplex := coalesce((v_f->>'duplex')::boolean, false);
      -- Extras only when the shop has a rate for them (0 / missing = not offered).
      v_binding := coalesce((v_f->>'binding')::boolean, false) and coalesce((v_shop.rates ->> 'binding')::numeric, 0) > 0;
      v_lam := coalesce((v_f->>'lamination')::boolean, false) and coalesce((v_shop.rates ->> 'lamination')::numeric, 0) > 0;
      v_range := nullif(left(v_f->>'page_range', 60), '');
      v_price := public.file_price(v_shop.rates, v_pages, v_copies, v_color, v_duplex, v_binding, v_lam);
    end if;
    v_total := v_total + v_price;
    v_path := v_shop.id::text || '/' || v_order.id::text || '/' || v_i::text || '-' ||
      left(regexp_replace(coalesce(v_f->>'name','file'), '[^A-Za-z0-9._-]', '_', 'g'), 80);
    v_paths := v_paths || v_path;
    insert into public.order_files (order_id, shop_id, storage_path, file_name, mime, size_bytes,
        total_pages, page_range, pages_to_print, copies, color, duplex, price, item_kind, photos, binding, lamination)
      values (v_order.id, v_shop.id, v_path, left(coalesce(v_f->>'name','file'), 200), v_f->>'mime',
        (v_f->>'size')::bigint, v_total_pages, v_range, v_pages, v_copies, v_color, v_duplex, v_price,
        v_kind, v_photos, v_binding, v_lam);
  end loop;

  update public.orders set total = v_total where id = v_order.id;

  return query select v_order.id, v_order.access_key, v_token, v_shop.id, v_total, v_paths;
end $$;
grant execute on function public.create_order(text, text, text, jsonb, uuid, uuid) to anon, authenticated;

-- ============ 2. reorder (from v23) with p_pass ============
-- The old 3-argument version is replaced (older pages call it with 3 named arguments: p_pass has a default).
drop function if exists public.reorder(uuid, uuid, jsonb);
create or replace function public.reorder(p_order_id uuid, p_key uuid, p_items jsonb, p_pass uuid default null)
returns table (order_id uuid, access_key uuid, token int, shop_id uuid, total numeric)
language plpgsql security definer set search_path = public as $$
declare
  v_src public.orders;
  v_shop public.shops;
  v_pro boolean;
  v_order public.orders;
  v_token int;
  v_total numeric(10,2) := 0;
  v_item jsonb;
  v_f public.order_files;
  v_i int := 0;
  v_copies int;
  v_color boolean;
  v_binding boolean;
  v_lam boolean;
  v_price numeric(10,2);
  v_path text;
  v_bytes bigint := 0;
  v_max bigint;
  v_ip text;
  v_seen uuid[] := '{}';
  v_counter_id uuid;
  v_counter_name text;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Kolkata')) at time zone 'Asia/Kolkata';
  v_mode text;
  v_cap_shop bigint;
  v_cap_all bigint;
begin
  select * into v_src from public.orders o where o.id = p_order_id and o.access_key = p_key;
  if not found then raise exception 'Order not found'; end if;
  if v_src.files_deleted then raise exception 'The files of this order are already deleted. Please send them again.'; end if;
  if v_src.status not in ('received', 'printing', 'ready', 'done') then raise exception 'This order cannot be printed again'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'No files';
  end if;
  if jsonb_array_length(p_items) > 20 then raise exception 'Max 20 files per order'; end if;

  select * into v_shop from public.shops s where s.id = v_src.shop_id for update;
  if not found or v_shop.blocked then raise exception 'Shop not found'; end if;
  if not v_shop.is_open then raise exception 'Shop is closed right now'; end if;

  -- Same anti-spam as create_order.
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.order_rate where created_at < now() - interval '1 day';
    if (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many orders from this network. Please wait a few minutes and try again.';
    end if;
  end if;
  if (select count(*) from public.orders o where o.shop_id = v_shop.id and o.status = 'uploading'
        and o.created_at > now() - interval '30 minutes') >= 20
     or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 60 then
    raise exception 'This shop is getting too many orders right now. Please try again in a few minutes.';
  end if;

  -- v44: same "Block sender" and bot check as create_order.
  if v_ip is not null and exists (select 1 from public.shop_blocked_senders b where b.shop_id = v_shop.id and b.ip_hash = v_ip) then
    raise exception 'This shop is not accepting orders from your network.';
  end if;
  v_mode := coalesce((select order_captcha from public.app_settings where id = 1), 'auto');
  if v_mode = 'always' or (v_mode = 'auto' and (
       (v_ip is not null and (select count(*) from public.order_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 3)
       or (select count(*) from public.orders o where o.shop_id = v_shop.id and o.created_at > now() - interval '10 minutes') >= 20)) then
    if p_pass is null then raise exception 'captcha_required'; end if;
    delete from public.upload_pass up where up.created_at < now() - interval '1 hour';
    delete from public.upload_pass up where up.id = p_pass and up.created_at > now() - interval '10 minutes';
    if not found then raise exception 'captcha_required'; end if;
  end if;

  -- Check every item before anything is written: own files only, once each, copies 1-100, plan still allows it.
  v_pro := public.is_pro(v_shop);
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' or coalesce(v_item->>'file_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'File not found';
    end if;
    select * into v_f from public.order_files f where f.id = (v_item->>'file_id')::uuid and f.order_id = v_src.id;
    if not found or v_f.id = any (v_seen) then raise exception 'File not found'; end if;
    v_seen := v_seen || v_f.id;
    if coalesce(v_item->>'copies', '') !~ '^[0-9]{1,3}$' then raise exception 'Copies must be from 1 to 100'; end if;
    if (v_item->>'copies')::int not between 1 and 100 then raise exception 'Copies must be from 1 to 100'; end if;
    if v_item ? 'color' and jsonb_typeof(v_item->'color') <> 'boolean' then raise exception 'Bad print option'; end if;
    if v_f.item_kind = 'passport' and not v_pro then raise exception 'Passport photo sheet is not available at this shop'; end if;
    if v_f.item_kind = 'idcard' and not v_pro then raise exception 'ID card sheet is not available at this shop'; end if;
    v_bytes := v_bytes + coalesce(v_f.size_bytes, 0);
  end loop;
  v_max := public.plan_order_bytes(v_shop);
  if v_bytes > v_max then raise exception 'This shop accepts up to % MB per order', v_max / 1048576; end if;

  -- v44: same storage budgets as create_order (the copies are new objects in this shop's folder).
  v_cap_shop := public.shop_storage_bytes(v_shop);
  v_cap_all := public.storage_budget_bytes();
  if v_ip is not null then
    if public.ip_pending_bytes(v_ip, null) + v_bytes > public.ip_pending_cap_bytes()
       or public.ip_pending_bytes(v_ip, v_shop.id) + v_bytes > greatest(v_max, v_cap_shop / 2) then
      raise exception 'Too many unfinished uploads from your network right now. Please wait a few minutes and try again.';
    end if;
  end if;
  if public.live_file_bytes(v_shop.id) + v_bytes > v_cap_shop then
    raise exception 'This shop''s file space is full right now. Please ask the shop to finish or clear old orders, then try again.';
  end if;
  if public.live_file_bytes(null) + v_bytes > v_cap_all then
    raise exception 'Uploads are paused for a short while because the service is very busy. Please try again later.';
  end if;
  if v_ip is not null then insert into public.order_rate (ip_hash) values (v_ip); end if;

  -- Same counter as before (if it still exists and the plan still allows it), else the main queue.
  if v_src.counter_id is not null then
    select c.id, c.name into v_counter_id, v_counter_name
      from public.counters c where c.id = v_src.counter_id and c.shop_id = v_shop.id
        and (v_pro or c.id in (
          select c2.id from public.counters c2 where c2.shop_id = v_shop.id
          order by c2.created_at, c2.id limit public.free_counter_limit()));
  end if;

  select coalesce(max(o.token), 0) + 1 into v_token
    from public.orders o where o.shop_id = v_shop.id and o.created_at >= v_day_start;

  insert into public.orders (shop_id, token, customer_name, note, counter_id, counter_name, lang)
    values (v_shop.id, v_token, v_src.customer_name, v_src.note, v_counter_id, v_counter_name, v_src.lang)
    returning * into v_order;
  -- v44: remember the network, so "Block sender" and the per-network upload limit also cover reprints.
  if v_ip is not null then
    insert into public.order_senders (order_id, shop_id, ip_hash) values (v_order.id, v_shop.id, v_ip);
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_i := v_i + 1;
    select * into v_f from public.order_files f where f.id = (v_item->>'file_id')::uuid and f.order_id = v_src.id;
    v_copies := (v_item->>'copies')::int;
    v_binding := false;
    v_lam := false;
    if v_f.item_kind = 'passport' then
      v_color := true;
      v_price := round(v_f.pages_to_print * v_copies * coalesce((v_shop.rates ->> 'passport_sheet')::numeric, 40), 2);
    elsif v_f.item_kind = 'idcard' then
      v_color := coalesce((v_item->>'color')::boolean, v_f.color);
      v_price := round(v_copies * coalesce((v_shop.rates ->> 'idcard_sheet')::numeric, 20), 2);
    else
      v_color := coalesce((v_item->>'color')::boolean, v_f.color);
      v_binding := v_f.binding and coalesce((v_shop.rates ->> 'binding')::numeric, 0) > 0;
      v_lam := v_f.lamination and coalesce((v_shop.rates ->> 'lamination')::numeric, 0) > 0;
      v_price := public.file_price(v_shop.rates, v_f.pages_to_print, v_copies, v_color, v_f.duplex, v_binding, v_lam);
    end if;
    v_total := v_total + v_price;
    v_path := v_shop.id::text || '/' || v_order.id::text || '/' || v_i::text || '-' ||
      left(regexp_replace(coalesce(v_f.file_name, 'file'), '[^A-Za-z0-9._-]', '_', 'g'), 80);
    insert into public.order_files (order_id, shop_id, storage_path, file_name, mime, size_bytes,
        total_pages, page_range, pages_to_print, copies, color, duplex, price, item_kind, photos, binding, lamination, source_path)
      values (v_order.id, v_shop.id, v_path, v_f.file_name, v_f.mime, v_f.size_bytes,
        v_f.total_pages, v_f.page_range, v_f.pages_to_print, v_copies, v_color, v_f.duplex, v_price,
        v_f.item_kind, v_f.photos, v_binding, v_lam, v_f.storage_path);
  end loop;

  update public.orders set total = v_total where id = v_order.id;

  return query select v_order.id, v_order.access_key, v_token, v_shop.id, v_total;
end $$;
revoke all on function public.reorder(uuid, uuid, jsonb, uuid) from public;
grant execute on function public.reorder(uuid, uuid, jsonb, uuid) to anon, authenticated;

-- ============ 3. coupons (from v42) ============
create or replace function public.coupon_check(p_shop uuid, p_code text, p_log boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_pending int;
  v_err text;
  v_blocked boolean;
  v_found boolean;
begin
  select s.blocked into v_blocked from public.shops s where s.id = p_shop;
  if not found or coalesce(v_blocked, false) then return jsonb_build_object('ok', false, 'error', 'blocked'); end if;
  if not coalesce((select coupons_enabled from public.app_settings where id = 1), true) then
    return jsonb_build_object('ok', false, 'error', 'disabled');
  end if;
  if (select count(*) from public.coupon_tries where shop_id = p_shop and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code;
  v_found := found;
  if v_found then
    select count(distinct k.shop_id) into v_pending from public.coupon_checkouts k
      where k.code = v_code and k.paid_at is null and k.shop_id <> p_shop and k.created_at > now() - interval '30 minutes';
  end if;
  if not v_found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses + coalesce(v_pending, 0) >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = p_shop) then v_err := 'already';
  -- v44: a free-days Plus code on a running Pro plan would turn all the paid Pro time into Plus.
  elsif v_c.kind <> 'percent' and v_c.tier = 'plus'
        and exists (select 1 from public.shops s where s.id = p_shop and public.is_pro(s) and not public.is_plus(s)) then
    v_err := 'tier_higher_than_paid';
  end if;
  if v_err is not null then
    if coalesce(p_log, true) then insert into public.coupon_tries (shop_id) values (p_shop); end if;
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  return jsonb_build_object('ok', true, 'kind', v_c.kind, 'code', v_c.code, 'percent', v_c.percent, 'mode', v_c.mode,
    'offer_id', v_c.offer_id, 'tiers', to_jsonb(v_c.tiers), 'periods', to_jsonb(v_c.periods), 'days', v_c.days, 'tier', v_c.tier,
    'expires_at', v_c.expires_at);
end $$;
revoke all on function public.coupon_check(uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.coupon_check(uuid, text, boolean) to service_role;

create or replace function public.redeem_coupon(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_shop public.shops;
  v_c public.coupons;
  v_code text := upper(trim(coalesce(p_code, '')));
  v_tier text;
  v_end timestamptz;
  v_err text;
begin
  select * into v_shop from public.shops where owner_id = auth.uid() for update;
  if not found then raise exception 'not allowed'; end if;
  if v_shop.blocked then raise exception 'not allowed'; end if;
  if not coalesce((select coupons_enabled from public.app_settings where id = 1), true) then
    return jsonb_build_object('ok', false, 'error', 'disabled');
  end if;
  if (select count(*) from public.coupon_tries where shop_id = v_shop.id and created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many');
  end if;
  select * into v_c from public.coupons where code = v_code for update;
  -- % code: nothing is redeemed here; the Plan tab checks it through create-subscription and applies it at payment.
  if found and v_c.active and v_c.kind = 'percent' then
    return jsonb_build_object('ok', false, 'error', 'checkout', 'code', v_code);
  end if;
  if not found or not v_c.active then v_err := 'not_found';
  elsif v_c.expires_at is not null and v_c.expires_at <= now() then v_err := 'expired';
  elsif v_c.max_uses is not null and v_c.uses >= v_c.max_uses then v_err := 'used_up';
  elsif exists (select 1 from public.coupon_redemptions r where r.code = v_code and r.shop_id = v_shop.id) then v_err := 'already';
  -- v44: a free-days code for a higher plan than the running Pro plan is refused (it would upgrade all the paid
  -- Pro time to Plus). It can be used once the current plan has ended. Counts as a try (no free code check).
  elsif v_c.tier = 'plus' and public.is_pro(v_shop) and not public.is_plus(v_shop) then v_err := 'tier_higher_than_paid';
  end if;
  if v_err is not null then
    insert into public.coupon_tries (shop_id) values (v_shop.id);
    return jsonb_build_object('ok', false, 'error', v_err);
  end if;
  v_tier := case when public.is_plus(v_shop) or v_c.tier = 'plus' then 'plus' else 'pro' end;
  v_end := greatest(coalesce(v_shop.plan_expires_at, now()), now()) + make_interval(days => v_c.days);
  update public.shops set plan = v_tier, plan_expires_at = v_end where id = v_shop.id;
  update public.coupons set uses = uses + 1 where code = v_code;
  insert into public.coupon_redemptions (code, shop_id, user_id, days, until) values (v_code, v_shop.id, auth.uid(), v_c.days, v_end);
  insert into public.admin_log (admin_id, action, shop_id, detail)
    values (null, 'coupon_redeemed', v_shop.id, jsonb_build_object('code', v_code, 'days', v_c.days, 'until', v_end,
            'before', v_shop.plan_expires_at, 'plan', v_tier, 'plan_before', v_shop.plan));
  return jsonb_build_object('ok', true, 'until', v_end, 'days', v_c.days, 'plan', v_tier);
end $$;
revoke all on function public.redeem_coupon(text) from public, anon;
grant execute on function public.redeem_coupon(text) to authenticated;

-- ============ 4. report_client_error (from v39) ============
create table if not exists public.client_error_rate (
  id bigint generated always as identity primary key,
  ip_hash text not null,
  created_at timestamptz not null default now()
);
create index if not exists client_error_rate_ip_idx on public.client_error_rate (ip_hash, created_at);
create index if not exists client_error_rate_created_idx on public.client_error_rate (created_at);
alter table public.client_error_rate enable row level security;
revoke all on public.client_error_rate from anon, authenticated;

create or replace function public.report_client_error(p_source text, p_message text, p_where text default null,
  p_route text default null, p_version text default null, p_ua text default null, p_stack text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_src text := case when p_source in ('web', 'app', 'desktop') then 'client-' || p_source else 'client-web' end;
  v_msg text;
  v_stack text;
  v_ip text;
begin
  v_msg := left(regexp_replace(regexp_replace(
             coalesce(nullif(trim(p_message), ''), 'unknown error') || coalesce(' @ ' || left(nullif(trim(p_where), ''), 80), ''),
             '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<email>', 'g'),
             'eyJ[A-Za-z0-9._-]{20,}', '<token>', 'g'), 300);
  v_stack := left(regexp_replace(regexp_replace(nullif(trim(p_stack), ''),
             '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '<email>', 'g'),
             'eyJ[A-Za-z0-9._-]{20,}', '<token>', 'g'), 2000);
  -- v44: at most 20 reports per 10 minutes from one network (counted before the shared cap, so one network
  -- cannot use up the 300 for everyone)
  v_ip := public.request_ip_hash();
  if v_ip is not null then
    delete from public.client_error_rate where created_at < now() - interval '1 hour';
    if (select count(*) from public.client_error_rate r where r.ip_hash = v_ip and r.created_at > now() - interval '10 minutes') >= 20 then
      return;
    end if;
    insert into public.client_error_rate (ip_hash) values (v_ip);
  end if;
  -- at most 300 client reports per 10 minutes in total, and the same message once per 5 minutes
  if (select count(*) from public.ops_events where source like 'client-%' and created_at > now() - interval '10 minutes') >= 300 then return; end if;
  if exists (select 1 from public.ops_events where source = v_src and message = v_msg and created_at > now() - interval '5 minutes') then return; end if;
  insert into public.ops_events (source, level, message, route, app_version, ua, stack)
  values (v_src, 'client', v_msg,
          left(regexp_replace(nullif(trim(p_route), ''), '[?#].*$', ''), 120),
          left(nullif(trim(p_version), ''), 40), left(nullif(trim(p_ua), ''), 300), v_stack);
end $$;
revoke all on function public.report_client_error(text, text, text, text, text, text, text) from public;
grant execute on function public.report_client_error(text, text, text, text, text, text, text) to anon, authenticated;

-- ============ 5. files_deleted only when the files are gone ============
-- Runs before orders_purge_personal (triggers fire in name order), which renames the paths.
create or replace function public.orders_files_gone_guard()
returns trigger language plpgsql security definer set search_path = public, storage as $$
begin
  if new.files_deleted and not coalesce(old.files_deleted, false)
     and coalesce(auth.role(), '') = 'authenticated'
     and exists (select 1 from public.order_files f
                 join storage.objects so on so.bucket_id = 'uploads' and so.name in (f.storage_path, f.storage_path || '.thumb.jpg')
                 where f.order_id = new.id) then
    raise exception 'Some files of this order could not be deleted. Please try again.';
  end if;
  return new;
end $$;
drop trigger if exists orders_files_gone_guard on public.orders;
create trigger orders_files_gone_guard before update of files_deleted on public.orders
  for each row execute function public.orders_files_gone_guard();

notify pgrst, 'reload schema';

-- ======================================================================
-- migrations/2026-11-26-v45-grant-admins-insert.sql
-- ======================================================================
-- PrintQR v45 migration (2026-11-26): admin-action "Make Support" inserts into public.admins with the
-- service role, which only had SELECT (v20, v30). Without INSERT it fails with
-- "DB 403: 42501 permission denied for table admins". Safe to run more than once (GRANT is idempotent).
-- Already applied by hand in production on 2026-11-26.
grant insert on public.admins to service_role;

-- ======================================================================
-- migrations/2026-11-27-v46-grant-admins-delete.sql
-- ======================================================================
-- PrintQR v46 migration (2026-11-27): admin-action "Remove admin" (bug #49) deletes a row from public.admins
-- with the service role, which only had SELECT (v20, v30) and INSERT (v45). Without DELETE it would fail with
-- "DB 403: 42501 permission denied for table admins". Safe to run more than once (GRANT is idempotent).
grant delete on public.admins to service_role;

-- ======================================================================
-- migrations/2026-11-28-v47-single-owner.sql
-- ======================================================================
-- PrintQR v47 migration (2026-11-28): only ONE Owner admin (the app owner's own login). Every other admin is Support.
--   1. If more than one Owner exists, the oldest Owner (first admin) stays Owner; the rest become Support.
--   2. A unique index makes a second Owner impossible, whatever path tries it.
--   3. New admins default to 'support'.
--   4. admin_set_role(): nobody can be made Owner and the Owner's role cannot be changed; only Support stays.
--      (Remove admin in admin-action also refuses the Owner.)
-- Safe to run more than once. Needs v39 (admins.role, admin_set_role, admin_log).

-- 1. Keep exactly one Owner.
do $$
declare v_keep uuid;
begin
  if (select count(*) from public.admins where role = 'owner') > 1 then
    select user_id into v_keep from public.admins where role = 'owner' order by created_at, user_id limit 1;
    insert into public.admin_log (admin_id, action, shop_id, detail)
      select v_keep, 'role_changed', null, jsonb_build_object('user_id', a.user_id, 'role', 'support', 'before', 'owner', 'reason', 'single_owner_v47')
      from public.admins a where a.role = 'owner' and a.user_id <> v_keep;
    update public.admins set role = 'support' where role = 'owner' and user_id <> v_keep;
  end if;
end $$;

-- 2. At most one Owner row, ever.
create unique index if not exists admins_single_owner on public.admins ((role)) where role = 'owner';

-- 3. A new admin is Support unless said otherwise (and the index above blocks a second Owner anyway).
alter table public.admins alter column role set default 'support';

-- 4. Roles are fixed: the Owner stays Owner, nobody else can become Owner.
create or replace function public.admin_set_role(p_user uuid, p_role text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_old text;
begin
  if not public.is_owner_admin() then raise exception 'not allowed'; end if;
  if p_role not in ('owner', 'support') then raise exception 'bad role'; end if;
  select role into v_old from public.admins where user_id = p_user for update;
  if not found then raise exception 'not an admin'; end if;
  if v_old = p_role then return; end if;
  raise exception 'owner fixed';
end $$;
revoke all on function public.admin_set_role(uuid, text) from public, anon;
grant execute on function public.admin_set_role(uuid, text) to authenticated;
